// PEQUENOS-ALMOÇOS - ABRIL (TODOS OS 30 DIAS)
// ==========================================

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SMOOTHIE_MORANGO_CHIA + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de morangos limpos</li><li>1 colher de sopa de sementes de chia</li><li>200 ml de bebida de amêndoa</li></ul><h3>Preparação:</h3><ol><li><b>Triturar:</b> Coloque os morangos lavados e a bebida de amêndoa no liquidificador. Triture até obter um batido homogéneo.</li><li><b>Hidratar:</b> Adicione as sementes de chia, misture bem com uma colher e deixe repousar durante 5 minutos para que as sementes expandam antes de beber.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_AVEIA_AMENDOA_MEL + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de sopa de flocos de aveia</li><li>250 ml de água ou leite</li><li>1 colher de sobremesa de mel</li><li>Amêndoas laminadas</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Leve os flocos de aveia ao lume com a água ou leite, mexendo sempre até engrossar e formar uma papa.</li><li><b>Finalizar:</b> Transfira para uma taça, adoce com o mel e decore o topo com as amêndoas laminadas ligeiramente tostadas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_TORRADA_ABACATE_OVO + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão de centeio integral</li><li>1/2 abacate maduro</li><li>1 ovo cozido ou escalfado</li><li>Sal e pimenta preta</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Toste a fatia de pão de centeio na torradeira até ficar estaladiça.</li><li><b>Montagem:</b> Esmague o abacate com um garfo e espalhe sobre o pão. Coloque o ovo cortado em rodelas por cima e tempere com uma pitada de sal e pimenta.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_IOGURTE_GRANOLA_TROPICAL + "', '<h3>Ingredientes:</h3><ul><li>1 iogurte natural ou vegetal</li><li>3 colheres de sopa de granola caseira</li><li>Cubos de manga e ananás fresco</li></ul><h3>Preparação:</h3><ol><li><b>Camadas:</b> Numa taça larga, coloque o iogurte natural como base protetora.</li><li><b>Decorar:</b> Adicione a granola de um dos lados e distribua os cubos de fruta tropical fresca pelo espaço restante antes de servir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_PANQUECAS_ESPELTA + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de farinha de espelta</li><li>1 ovo médio</li><li>150 ml de bebida vegetal</li><li>1 colher de chá de fermento em pó</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Misture bem a farinha de espelta, o fermento, o ovo e a bebida vegetal com um batedor de varas até obter uma consistência lisa.</li><li><b>Cozinhar:</b> Verta pequenas porções numa frigideira antiaderente quente. Vire as panquecas assim que começarem a surgir bolhas na superfície.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SMOOTHIE_BOWL_SPIRULINA + "', '<h3>Ingredientes:</h3><ul><li>1 banana congelada em rodelas</li><li>1/2 chávena de bebida de coco</li><li>1 colher de chá de spirulina em pó</li><li>Bagas de goji para decorar</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Triture a banana congelada com a bebida de coco e a spirulina no liquidificador até formar um creme espesso e esverdeado.</li><li><b>Acompanhar:</b> Verta o preparado para uma taça profunda e decore a superfície com as bagas de goji.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_PUDIM_CHIA_KIWI + "', '<h3>Ingredientes:</h3><ul><li>3 colheres de sopa de sementes de chia</li><li>200 ml de leite de coco leve</li><li>1 kiwi maduro</li></ul><h3>Preparação:</h3><ol><li><b>Repouso:</b> Misture muito bem as sementes de chia com o leite de coco numa taça e guarde no frigorífico durante a noite.</li><li><b>Fruta:</b> Na manhã seguinte, descasque o kiwi, corte em pedaços pequenos ou esmague e coloque sobre o pudim gelatinoso.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_TORRADA_AMENDOIM_MIRTILO + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão de mistura ou forma</li><li>1 colher de sopa de manteiga de amendoim pura</li><li>1 punhado de mirtilos frescos</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Toste bem a fatia de pão a gosto.</li><li><b>Barrar:</b> Cubra a superfície com a manteiga de amendoim e distribua os mirtilos lavados por cima, pressionando ligeiramente para que não caiam.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_MEXIDO_TOFU_TOMATE + "', '<h3>Ingredientes:</h3><ul><li>150 g de tofu firme</li><li>1 tomate maduro em cubos</li><li>1/2 colher de chá de curcuma</li><li>Azeite e sal</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Esmague o bloco de tofu com a ajuda de um garfo até obter uma textura granulada.</li><li><b>Cozinhar:</b> Numa frigideira com um fio de azeite, salteie os cubos de tomate. Junte o tofu esmagado, a curcuma e mexa por 5 minutos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_PAPAS_MILHO_COCO + "', '<h3>Ingredientes:</h3><ul><li>3 colheres de sopa de sêmola de milho</li><li>250 ml de leite de coco</li><li>1 colher de sopa de coco ralado</li></ul><h3>Preparação:</h3><ol><li><b>Ferver:</b> Leve o leite de coco ao lume num tacho pequeno até levantar fervura.</li><li><b>Engrossar:</b> Adicione a sêmola de milho em chuva, mexendo sempre em lume brando até obter uma papa suave. Sirva polvilhado com o coco ralado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SMOOTHIE_BANANA_ESPINAFRE + "', '<h3>Ingredientes:</h3><ul><li>1 banana madura</li><li>1 de chávena de folhas de espinafres novas</li><li>200 ml de água ou bebida de aveia</li></ul><h3>Preparação:</h3><ol><li><b>Processar:</b> Coloque a banana, as folhas de espinafres bem lavadas e o líquido escolhido no copo do liquidificador.</li><li><b>Bater:</b> Processe na velocidade máxima até os espinafres ficarem totalmente desfeitos e o batido verde apresentar uma textura aveludada.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_TACA_ACAI_CANHAMO + "', '<h3>Ingredientes:</h3><ul><li>100 g de polpa de açaí congelada</li><li>1 banana pequena</li><li>1 colher de sopa de sementes de cânhamo descascadas</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Triture a polpa de açaí com a banana no liquidificador até obter um creme gelado e homogéneo.</li><li><b>Servir:</b> Transfira o preparado para uma taça e polvilhe o topo com as sementes de cânhamo ricas em proteína.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_TORRADA_HUMUS_PIMENTOS + "', '<h3>Ingredientes:</h3><ul><li>1 fatia grande de pão rústico ou alentejano</li><li>2 colheres de sopa de húmus de grão</li><li>Tiras de pimento assado</li></ul><h3>Preparação:</h3><ol><li><b>Tostar:</b> Grelhe ou toste a fatia de pão até dourar.</li><li><b>Montar:</b> Barre uma camada generosa de húmus sobre o pão quente e disponha as tiras de pimento assado por cima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_MUESLI_AVELA + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de sopa de muesli tradicional sem açúcar</li><li>150 ml de iogurte natural ou leite</li><li>Avelãs picadas</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Coloque o muesli numa taça e verta o leite ou envolva o iogurte natural.</li><li><b>Repousar:</b> Deixe repousar durante 3 minutos para amaciar ligeiramente os cereais e finalize salpicando as avelãs picadas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_QUINOA_MACA + "', '<h3>Ingredientes:</h3><ul><li>1/2 de chávena de quinoa cozida</li><li>1/2 maçã cortada em cubos pequenos</li><li>1/2 colher de chá de canela em pó</li><li>100 ml de leite vegetal</li></ul><h3>Preparação:</h3><ol><li><b>Aquecer:</b> Num tacho pequeno, junte a quinoa já cozida, os cubos de maçã e o leite vegetal.</li><li><b>Apurar:</b> Cozinhe em lume brando até a maçã amaciar ligeiramente e perfume com a canela em pó antes de retirar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SMOOTHIE_MANGA_HORTELA + "', '<h3>Ingredientes:</h3><ul><li>1 de chávena de cubos de manga madura</li><li>200 ml de bebida de arroz</li><li>4 folhas de hortelã fresca</li></ul><h3>Preparação:</h3><ol><li><b>Liquidificar:</b> Junte os cubos de manga, a bebida de arroz e as folhas de hortelã fresca no liquidificador.</li><li><b>Bater:</b> Processe todos os ingredientes até obter um sumo cremoso, aromático e refrescante.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_PANQUECAS_BANANA_NOZ + "', '<h3>Ingredientes:</h3><ul><li>1 banana madura esmagada</li><li>1 ovo médio</li><li>2 colheres de sopa de aveia moída</li><li>Nozes picadas</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Misture energeticamente a banana esmagada com o ovo e a aveia moída até obter uma massa homogénea.</li><li><b>Cozinhar:</b> Coza pequenas porções numa frigideira antiaderente. Sirva as panquecas com as nozes picadas por cima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_PAPAS_SARRACENO_MORANGO + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de sopa de flocos de trigo sarraceno</li><li>250 ml de água</li><li>4 morangos frescos fatiados</li></ul><h3>Preparação:</h3><ol><li><b>Cozedura:</b> Coça os flocos de trigo sarraceno na água durante 5 a 7 minutos, mexendo sempre para não agarrar ao fundo.</li><li><b>Decorar:</b> Coloque as papas numa taça e decore a superfície com os morangos fatiados.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_TORRADA_QUEIJO_MEL + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão integral</li><li>1 fatia de queijo fresco ou requeijão</li><li>1 fio de mel silvestre</li></ul><h3>Preparação:</h3><ol><li><b>Tostar:</b> Toste a fatia de pão integral na torradeira.</li><li><b>Finalizar:</b> Disponha o queijo fresco sobre a torrada ainda quente e termine vertendo um fio fino de mel por cima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_IOGURTE_LINHACA_PAPAIA + "', '<h3>Ingredientes:</h3><ul><li>1 iogurte grego natural</li><li>1 colher de sopa de sementes de linhaça moídas</li><li>1/2 de chávena de papaia em cubos</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Numa taça individual, combine o iogurte grego com as sementes de linhaça moídas.</li><li><b>Incorporar:</b> Distribua os cubos de papaia por cima do iogurte e envolva levemente antes de consumir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SMOOTHIE_SILVESTRES + "', '<h3>Ingredientes:</h3><ul><li>1 de chávena de frutos silvestres congelados (amoras, mirtilos e framboesas)</li><li>200 ml de bebida de aveia</li></ul><h3>Preparação:</h3><ol><li><b>Bater:</b> Coloque a mistura de frutos silvestres congelados e a bebida de aveia no liquidificador.</li><li><b>Textura:</b> Triture na velocidade máxima durante cerca de 1 minuto até obter uma textura cremosa e sem pedaços.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_TAPIOCA_QUEIJO_TOMATE + "', '<h3>Ingredientes:</h3><ul><li>3 colheres de sopa de goma de tapioca hidratada</li><li>1 fatia de queijo magro</li><li>2 fatias de tomate</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Espalhe a tapioca numa frigideira antiaderente fria. Leve ao lume e deixe ligar até formar um disco.</li><li><b>Rechear:</b> Vire o disco de tapioca, coloque o queijo e o tomate, dobre ao meio e abafe até o queijo derreter.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_AVEIA_TAMARAS + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de sopa de flocos de aveia</li><li>250 ml de água</li><li>2 tâmaras picadas sem caroço</li></ul><h3>Preparação:</h3><ol><li><b>Cozinar:</b> Leve os flocos de aveia ao lume com a água e as tâmaras secas bem picadas.</li><li><b>Apurar:</b> Coza por 5 minutos mexendo sempre. As tâmaras vão adoçar as papas de forma natural.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SMOOTHIE_BOWL_ABACATE + "', '<h3>Ingredientes:</h3><ul><li>1/2 abacate maduro</li><li>1 banana pequena</li><li>100 ml de bebida vegetal</li><li>Sementes de abóbora para decorar</li></ul><h3>Preparação:</h3><ol><li><b>Creme:</b> Processe o abacate, a banana e a bebida vegetal no liquidificador até atingir um creme espesso.</li><li><b>Topping:</b> Verta para uma taça e salpique a superfície com as sementes de abóbora para dar textura.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_TORRADA_COGUMELOS + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão rústico</li><li>100 g de cogumelos limpos fatiados</li><li>1 dente de alho picado</li><li>Azeite</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Numa frigideira com um fio de azeite, salteie os cogumelos e o alho picado até ficarem dourados.</li><li><b>Servir:</b> Toste a fatia de pão rústico e coloque os cogumelos salteados bem quentes por cima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_MUFFIN_AVEIA_MACA + "', '<h3>Ingredientes:</h3><ul><li>1 de chávena de flocos de aveia</li><li>1 maçã média ralada</li><li>1 ovo médio</li><li>1 colher de chá de fermento e canela</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Envolva bem os flocos de aveia, a maçã ralada, o ovo, o fermento e a canela numa taça.</li><li><b>Forno:</b> Distribua a massa por formas de queque e leve ao forno pré-aquecido a 180 graus por 15 a 20 minutos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SMOOTHIE_PERA_CANELA + "', '<h3>Ingredientes:</h3><ul><li>1 pera madura cortada</li><li>200 ml de leite de amêndoa</li><li>1/2 colher de chá de canela em pó</li></ul><h3>Preparação:</h3><ol><li><b>Bater:</b> Introduza a pera em pedaços, o leite de amêndoa e a canela no copo do liquidificador.</li><li><b>Processar:</b> Misture tudo durante 1 minuto até obter um batido suave, aveludado e sem grumos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_PAPAS_CEVADA_MEL + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de sopa de flocos de cevada</li><li>250 ml de água ou leite</li><li>1 colher de sobremesa de mel</li></ul><h3>Preparação:</h3><ol><li><b>Cozedura:</b> Coloque os flocos de cevada a cozinhar no líquido a ferver durante cerca de 8 minutos, mexendo.</li><li><b>Adoçar:</b> Retire do lume, coloque o preparado numa taça e adicione o mel líquido por cima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_TORRADA_CAJU_BANANA + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão de forma integral</li><li>1 colher de sopa de manteiga de caju</li><li>1/2 banana fatiada</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Toste a fatia de pão de forma na torradeira até ficar crocante.</li><li><b>Decorar:</b> Barre a manteiga de caju uniformemente e distribua as rodelas de banana fresca por cima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_TACA_IOGURTE_ABOBORA + "', '<h3>Ingredientes:</h3><ul><li>1 iogurte natural</li><li>2 colheres de sopa de puré de abóbora cozida</li><li>Nozes para decorar e uma pitada de canela</li></ul><h3>Preparação:</h3><ol><li><b>Montagem:</b> Numa taça pequena, alterne camadas de iogurte natural com o puré de abóbora aromatizado com canela.</li><li><b>Finalizar:</b> Decore o topo com pedaços de nozes quebradas para adicionar um elemento crocante.</li></ol>');");

        // ==========================================
// ALMOÇOS - ABRIL (TODOS OS 30 DIAS)
// ==========================================

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_RISOTO_ESPARGOS + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de arroz próprio para risoto</li><li>1/2 molho de espargos verdes cortados</li><li>1 cebola pequena picada</li><li>Caldo de legumes quente</li></ul><h3>Preparação:</h3><ol><li><b>Refogado:</b> Faça um refogado leve com a cebola picada num fio de azeite. Adicione o arroz e deixe fritar ligeiramente.</li><li><b>Cozedura:</b> Vá deitando o caldo de legumes quente aos poucos, mexendo sempre à medida que o arroz absorve o líquido.</li><li><b>Espargos:</b> A meio do tempo de cozedura, introduza os pedações de espargos verdes e cozinhe até o arroz ficar cremoso e al dente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SALADA_QUINOA_GRAO + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de quinoa cozida fria</li><li>1 chávena de grão de bico cozido</li><li>1/2 pepino e tomate em cubos</li><li>Azeite e sumo de limão</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Numa saladeira grande, combine a quinoa cozida com o grão de bico bem lavado e escorrido.</li><li><b>Legumes:</b> Adicione os cubos de pepino e de tomate fresco ao preparado.</li><li><b>Tempero:</b> Regue com azeite virgem extra, sumo de limão e envolva tudo delicadamente antes de servir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_MASSA_PESTO_PINHOES + "', '<h3>Ingredientes:</h3><ul><li>150 g de massa à escolha</li><li>2 colheres de sopa de molho pesto caseiro</li><li>1 colher de sopa de pinhões</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Coza a massa em água abundante com sal seguindo as indicações do pacote para ficar al dente.</li><li><b>Pinhões:</b> Toste ligeiramente os pinhões numa frigideira antiaderente sem qualquer gordura, tendo cuidado para não queimar.</li><li><b>Envolver:</b> Escorra a massa, misture o molho pesto uniformemente e salpique com os pinhões tostados por cima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_CHILI_LENTILHAS_DOCE + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de lentilhas castanhas cozidas</li><li>1/2 chávena de milho doce</li><li>200 ml de polpa de tomate</li><li>1/2 pimento vermelho em cubos</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Refogue a cebola e o pimento vermelho numa panela pequena com um fio de azeite.</li><li><b>Estufar:</b> Adicione a polpa de tomate, as lentilhas e o milho doce bem escorrido. Tempere com uma pitada de sal.</li><li><b>Apurar:</b> Deixe cozinhar em lume brando por 15 minutos até obter um molho espesso e aveludado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_ALMONDEGAS_BERINJELA + "', '<h3>Ingredientes:</h3><ul><li>6 almôndegas de beringela prontas</li><li>1 chávena de molho de tomate</li><li>150 g de massa integral cozida</li></ul><h3>Preparação:</h3><ol><li><b>Aquecer:</b> Coloque o molho de tomate numa panela e introduza as almôndegas de beringela para tomarem gosto.</li><li><b>Massa:</b> Garanta que a massa integral está quente e bem escorrida.</li><li><b>Servir:</b> Disponha as almôndegas e o molho aromático sobre a cama de massa integral quente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_TORTA_ESPINAFRES + "', '<h3>Ingredientes:</h3><ul><li>250 g de espinafres frescos</li><li>4 ovos batidos</li><li>50 g de queijo ralado magro</li><li>Azeite e alho</li></ul><h3>Preparação:</h3><ol><li><b>Espinafres:</b> Salteie os espinafres com alho e azeite numa frigideira até murcharem. Escorra muito bem o líquido restante.</li><li><b>Misturar:</b> Junte os espinafres picados aos ovos batidos e adicione o queijo ralado, envolvendo bem.</li><li><b>Forno:</b> Verta num tabuleiro forrado com papel vegetal e leve ao forno a 180 graus até firmar. Enrole com cuidado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_ESTUFADO_FEIJAO_BRANCO + "', '<h3>Ingredientes:</h3><ul><li>400 g de feijão branco cozido</li><li>1 cenoura grande às rodelas</li><li>1/2 lata de tomate em pedaços</li><li>1 folha de louro e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Puxe uma cebola picada e as rodelas de cenoura em azeite juntamente com a folha de louro.</li><li><b>Estufar:</b> Adicione o tomate em pedaços e meio copo de água. Deixe a cenoura cozer até ficar tenra.</li><li><b>Finalizar:</b> Junte o feijão branco cozido, retifique o sal e deixe apurar por 5 minutos antes de desligar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_HAMBURGUER_GRAO_BATATA + "', '<h3>Ingredientes:</h3><ul><li>2 hambúrgueres de grão de bico</li><li>2 batatas médias</li><li>Azeite e alecrim seco</li></ul><h3>Preparação:</h3><ol><li><b>Batatas:</b> Corte as batatas em gomos, tempere com um fio de azeite e alecrim e leve ao forno a assar até dourarem.</li><li><b>Hambúrguer:</b> Grelhe os hambúrgueres de grão numa frigideira antiaderente quente com um salpico de azeite.</li><li><b>Empratar:</b> Sirva os hambúrgueres bem quentes acompanhados pelos gomos de batata assada.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_COUSCOUS_LEGUMES + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de couscous</li><li>1/2 curgete e 1/2 pimento em cubos</li><li>1 cenoura pequena ralada</li><li>Azeite e sal</li></ul><h3>Preparação:</h3><ol><li><b>Hidratar:</b> Verta água a ferver temperada com sal sobre o couscous, abafe por 5 minutos e solte com um garfo.</li><li><b>Saltear:</b> Numa frigideira com azeite, salteie os cubos de curgete, pimento e a cenoura ralada até estarem al dente.</li><li><b>Misturar:</b> Junte os legumes salteados ao couscous morno e envolva suavemente antes de servir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_LASANHA_ABOBORINHA + "', '<h3>Ingredientes:</h3><ul><li>2 aboborinhas (curgetes) longas</li><li>Placas de lasanha prontas</li><li>200 g de queijo ricota ou vegetal</li><li>Molho de tomate</li></ul><h3>Preparação:</h3><ol><li><b>Laminar:</b> Corte as aboborinhas em fatias longitudinais finas com a ajuda de uma mandolina ou faca afiada.</li><li><b>Montar:</b> Num pirex de forno, alterne camadas de molho de tomate, fatias de aboborinha, placas de massa e queijo ricota.</li><li><b>Cozedura:</b> Termine com uma camada leve de queijo e leve ao forno a 180 graus por cerca de 35 minutos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SALADA_MACARRAO_TOMATE + "', '<h3>Ingredientes:</h3><ul><li>150 g de massa macarrão</li><li>1 chávena de tomates cherry</li><li>1/2 chávena de cubos de queijo feta</li><li>Azeite e orégãos</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Coza o macarrão, escorra e passe por água fria para interromper o aquecimento.</li><li><b>Juntar:</b> Numa taça grande, junte a massa fria, os tomates cherry cortados ao meio e os cubos de queijo feta.</li><li><b>Tempero:</b> Regue com um fio generoso de azeite virgem extra e polvilhe com orégãos secos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_ARROZ_FEIJAO_VAPOR + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de arroz cozido</li><li>1 chávena de feijão preto cozido</li><li>1 chávena de floretes de brócolos e cenoura</li></ul><h3>Preparação:</h3><ol><li><b>Vapor:</b> Coloque os floretes de brócolos e as rodelas de cenoura a cozer a vapor até ficarem tenros mas firmes.</li><li><b>Aquecer:</b> Misture o arroz cozido com o feijão preto numa panela pequena para aquecerem em conjunto.</li><li><b>Acompanhar:</b> Sirva a mistura reconfortante de arroz e feijão ao lado dos legumes cozidos a vapor.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_TORTILHA_BATATA_ALHO + "', '<h3>Ingredientes:</h3><ul><li>3 batatas médias em rodelas finas</li><li>2 dentes de alho picados</li><li>4 ovos inteiros batidos</li><li>Azeite</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Coza lentamente as rodelas de batatas e o alho picado em azeite abundante até estarem macias (sem fritar). Escorra.</li><li><b>Mistura:</b> Envolva as batatas mornas e escorridas nos ovos batidos dentro de uma taça com uma pitada de sal.</li><li><b>Frigideira:</b> Verta numa frigideira antiaderente quente com um fio de azeite e vire a tortilha com um prato para dourar os dois lados.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_QUICHE_LEGUMES + "', '<h3>Ingredientes:</h3><ul><li>1 base de massa quebrada para tartes</li><li>1 chávena de legumes variados cozidos (cenoura, ervilhas, milho)</li><li>3 ovos e 150 ml de natas ligeiras</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Forre uma tarteira com a massa quebrada e pique o fundo com um garfo.</li><li><b>Recheio:</b> Distribua os legumes cozidos bem escorridos sobre o fundo da massa quebrada.</li><li><b>Forno:</b> Cubra com os ovos batidos com as natas ligeiras e uma pitada de sal. Leve ao forno a 190 graus até dourar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SALADA_LENTILHAS_MACA + "', '<h3>Ingredientes:</h3><ul><li>200 g de lentilhas cozidas escorridas</li><li>1/2 maçã verde com casca em cubos</li><li>1/4 chávena de nozes picadas</li><li>Azeite</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Misture as lentilhas cozidas frias com os cubos de maçã verde numa saladeira.</li><li><b>Textura:</b> Adicione as nozes picadas para conferir um toque crocante à salada.</li><li><b>Tempero:</b> Regue com um fio de azeite virgem extra e mexa ligeiramente antes de consumir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_MASSA_TOMATE_AZEITONAS + "', '<h3>Ingredientes:</h3><ul><li>150 g de massa fusilli ou outra</li><li>200 ml de polpa de tomate caseira</li><li>1/4 chávena de azeitonas pretas às rodelas</li><li>Alho e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Molho:</b> Faça um refogado com alho e azeite, adicione a polpa de tomate e as rodelas de azeitonas pretas. Deixe apurar.</li><li><b>Massa:</b> Coza a massa em água e sal até ficar al dente e escorra a água por completo.</li><li><b>Misturar:</b> Adicione a massa escorvida diretamente na panela do molho de tomate e envolva bem antes de servir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_GRATINADO_COUVE_FLOR + "', '<h3>Ingredientes:</h3><ul><li>1 couve-flor média em floretes</li><li>300 ml de molho bechamel vegetal</li><li>50 g de queijo ralado para a cobertura</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Leve os floretes de couve-flor a cozer em água e sal ou a vapor até ficarem macios.</li><li><b>Montar:</b> Disponha a couve-flor cozida num pirex de forno e verta o molho bechamel uniformemente.</li><li><b>Gratinar:</b> Cubra a superfície com o queijo ralado e leve ao forno na função grill até fazer uma crosta dourada.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_EMPADAO_LENTILHAS + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de lentilhas castanhas cozidas</li><li>1 cebola e 1 cenoura picadas</li><li>Puré de batata caseiro</li><li>Polpa de tomate</li></ul><h3>Preparação:</h3><ol><li><b>Recheio:</b> Estufe as lentilhas com a cebola, a cenoura picada, a polpa de tomate e um fio de azeite até secar ligeiramente.</li><li><b>Montagem:</b> Num tabuleiro de forno, coloque metade do puré de batata, espalhe o recheio de lentilhas e cubra com o restante puré.</li><li><b>Dourar:</b> Pincele o topo com um pouco de leite vegetal e leve ao forno quente por 20 minutos até dourar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SALADA_FEIJAO_FRADE + "', '<h3>Ingredientes:</h3><ul><li>400 g de feijão-frade cozido</li><li>1 cebola pequena finamente picada</li><li>1 ovo cozido picado (opcional)</li><li>Salsa fresca, azeite e vinagre</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Lave e escorra muito bem o feijão-frade cozido. Transfira para uma taça larga.</li><li><b>Juntar:</b> Adicione a cebola picada, o ovo cozido em pedaços pequenos e uma quantidade generosa de salsa fresca.</li><li><b>Tempero:</b> Regue com azeite e vinagre a gosto, tempere com uma pitada de sal e reserve no frigorífico.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_TOFU_ERVAS_ARROZ + "', '<h3>Ingredientes:</h3><ul><li>150 g de tofu firme em fatias</li><li>1 colher de sobremesa de ervas finas (salsa, tomilho, orégãos)</li><li>1 chávena de arroz basmati cozido</li><li>Azeite</li></ul><h3>Preparação:</h3><ol><li><b>Grelhar:</b> Tempere as fatias de tofu com sal e as ervas finas. Grelhe numa frigideira antiaderente com azeite.</li><li><b>Acompanhar:</b> Certifique-se de que o arroz basmati está quente e solto.</li><li><b>Servir:</b> Disponha as fatias de tofu grelhadas aromáticas sobre ou ao lado da porção de arroz basmati.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_RISOTO_ABOBORA_SALVIA + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de arroz arbóreo</li><li>1 chávena de cubos pequenos de abóbora</li><li>4 folhas de sálvia fresca</li><li>Caldo de legumes quente</li></ul><h3>Preparação:</h3><ol><li><b>Arroz:</b> Puxe a cebola picada em azeite, junte o arroz e os cubos de abóbora, deixando fritar um minuto.</li><li><b>Cozedura:</b> Adicione o caldo de legumes quente aos poucos, mexendo sempre para libertar o goma do arroz.</li><li><b>Sálvia:</b> A meio do processo, junte as folhas de sálvia picadas e cozinhe até a abóbora estar desfeita e o arroz cremoso.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_CARIL_GRAO_ESPINAFRES + "', '<h3>Ingredientes:</h3><ul><li>400 g de grão de bico cozido</li><li>2 chávenas de espinafres frescos</li><li>200 ml de leite de coco leve</li><li>1 colher de sopa de pó de caril</li></ul><h3>Preparação:</h3><ol><li><b>Refogado:</b> Faça uma base com cebola e azeite, adicione o pó de caril e envolva por alguns segundos.</li><li><b>Apurar:</b> Junte o grão de bico e o leite de coco. Deixe cozinhar em lume brando durante 10 minutos para tomar gosto.</li><li><b>Verdes:</b> Introduza as folhas de espinafres frescos, mexa até murcharem e retire imediatamente do lume.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_CANELONES_TOFU + "', '<h3>Ingredientes:</h3><ul><li>Tubos de canelones prontos a rechear</li><li>200 g de tofu macio esmagado</li><li>1 chávena de molho de tomate caseiro</li><li>Noz-moscada</li></ul><h3>Preparação:</h3><ol><li><b>Recheio:</b> Tempere o tofu esmagado com uma pitada de sal e noz-moscada a gosto.</li><li><b>Rechear:</b> Introduza cuidadosamente o tofu temperado no interior dos tubos de canelones.</li><li><b>Forno:</b> Coloque os canelones num pirex, cubra na totalidade com o molho de tomate e leve ao forno a 180 graus tapado com alumínio.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SALADA_QUINOA_MANGA + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de quinoa cozida fria</li><li>1/2 manga madura em cubos pequenos</li><li>1/2 pimento vermelho picado</li><li>Sumo de lima e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Combinar:</b> Numa saladeira, misture a quinoa cozida fria com os cubos de manga e o pimento picado.</li><li><b>Frescura:</b> Se gostar, adicione umas folhas de coentros frescos picados ao preparado.</li><li><b>Tempero:</b> Regue com azeite virgem extra e sumo de lima fresco antes de envolver com cuidado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_MASSA_BROCOLOS_ALHO + "', '<h3>Ingredientes:</h3><ul><li>150 g de massa esparguete ou fusilli</li><li>1 chávena de brócolos em floretes muito pequenos</li><li>3 dentes de alho fatiados e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Coza a massa juntamente com os floretes de brócolos na mesma panela com água e sal. Escorra tudo.</li><li><b>Saltear:</b> Numa frigideira larga, doure as fatias de alho num fio generoso de azeite.</li><li><b>Envolver:</b> Adicione a massa e os brócolos escorridos à frigideira, salteie por 2 minutos e sirva quente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_HAMBURGUER_LENTILHAS_SALADA + "', '<h3>Ingredientes:</h3><ul><li>2 hambúrgueres de lentilhas</li><li>Folhas de alface e rúcula</li><li>1/2 pepino fatiado</li><li>Azeite para temperar</li></ul><h3>Preparação:</h3><ol><li><b>Grelhar:</b> Cozinhe os hambúrgueres de lentilhas numa frigideira antiaderente bem quente com um fio de azeite de ambos os lados.</li><li><b>Salada:</b> Prepare uma cama de folhas verdes mistas e pepino fatiado numa taça.</li><li><b>Servir:</b> Disponha os hambúrgueres quentes ao lado da salada fresca devidamente temperada com azeite.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_ESTUFADO_ERVILHAS_OVOS + "', '<h3>Ingredientes:</h3><ul><li>250 g de ervilhas (frescas ou congeladas)</li><li>200 ml de polpa de tomate</li><li>2 ovos inteiros</li><li>1 cebola pequena e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Refogue a cebola picada em azeite, adicione a polpa de tomate e junte as ervilhas com um pouco de água.</li><li><b>Cozer:</b> Deixe as ervilhas estufarem em lume brando até ficarem tenras. Tempere com sal.</li><li><b>Ovos:</b> Abra os ovos inteiros com cuidado sobre as ervilhas, tape o tacho e deixe escalfar no vapor por 5 minutos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SALADA_MACARRAO_MILHO + "', '<h3>Ingredientes:</h3><ul><li>150 g de massa macarrão cozida</li><li>1/2 de chávena de milho doce escorrido</li><li>1 cenoura ralada</li><li>2 colheres de sopa de maionese vegetal</li></ul><h3>Preparação:</h3><ol><li><b>Arrefecer:</b> Deixe a massa macarrão arrefecer por completo após a cozedura.</li><li><b>Misturar:</b> Numa taça, junte a massa fria, o milho doce e a cenoura finamente ralada.</li><li><b>Finalizar:</b> Envolva os ingredientes na maionese vegetal ligeira e reserve no frigorífico até ao momento de servir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_ARROZ_TOMATE_TOFU + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de arroz</li><li>2 tomates maduros bem picados</li><li>100 g de tofu em cubos grelhados</li><li>Cebola e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Arroz:</b> Faça um refogado com cebola e azeite, junte o tomate e o arroz. Adicione duas chávenas e meia de água a ferver.</li><li><b>Cozinhar:</b> Deixe o arroz cozer em lume brando até ficar malandrinho (com algum caldo restante).</li><li><b>Servir:</b> Coloque os cubos de tofu previamente grelhados por cima do arroz de tomate bem quente no prato.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_QUINOA_LEGUMES_TAHINI + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de quinoa cozida</li><li>1/2 curgete e cenoura em palitos</li><li>1 colher de sopa de pasta de tahini</li><li>Sumo de limão e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Numa frigideira com azeite, salteie os palitos de curgete e cenoura até ficarem al dente.</li><li><b>Molho:</b> Dilua a pasta de tahini com uma colher de sopa de água morna e umas gotas de sumo de limão.</li><li><b>Empratar:</b> Misture os legumes com a quinoa quente e regue uniformemente com o molho de tahini cremoso.</li></ol>');");

        // ==========================================
// JANTARES - ABRIL (TODOS OS 30 DIAS)
// ==========================================

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SOPA_ALFACE_HORTELA + "', '<h3>Ingredientes:</h3><ul><li>1 alface média cortada</li><li>1 batata e 1 cebola</li><li>4 folhas de hortelã fresca</li><li>Azeite e sal</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Coza a batata e a cebola cortadas num tacho com água temperada com sal.</li><li><b>Verdes:</b> Quando estiverem macias, adicione a alface em tiras finas e as folhas de hortelã, deixando ferver por 5 minutos.</li><li><b>Triturar:</b> Reduza tudo a um creme liso com a varinha mágica e finalize com um fio de azeite em cru.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_TOFU_GRELHADO_VERDE + "', '<h3>Ingredientes:</h3><ul><li>150 g de tofu firme</li><li>1/2 curgete em rodelas</li><li>1 chávena de floretes de brócolos</li><li>Azeite e ervas finas</li></ul><h3>Preparação:</h3><ol><li><b>Tofu:</b> Corte o tofu em fatias médias e grelhe numa chapa bem quente com um fio de azeite até dourar.</li><li><b>Legumes:</b> Na mesma chapa, grelhe os brócolos e as rodelas de curgete até ficarem al dente.</li><li><b>Servir:</b> Disponha o tofu e os legumes no prato, salpique com as ervas finas e regue com um fio de azeite.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SALADA_CAPRESE + "', '<h3>Ingredientes:</h3><ul><li>2 tomates maduros firmes</li><li>100 g de queijo mozarela fresco</li><li>Folhas de manjericão fresco</li><li>Azeite e orégãos</li></ul><h3>Preparação:</h3><ol><li><b>Cortar:</b> Lave bem os tomates e corte-os em rodelas médias, assim como o queijo mozarela fresco.</li><li><b>Montagem:</b> Intercale as rodelas de tomate e queijo num prato de servir, decorando com as folhas de manjericão.</li><li><b>Tempero:</b> Regue generosamente com azeite virgem extra e polvilhe com uma chuva de orégãos secos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_CREME_CENOURA_GENGIBRE + "', '<h3>Ingredientes:</h3><ul><li>4 cenouras grandes</li><li>1 batata e 1 cebola</li><li>1 colher de chá de gengibre fresco ralado</li><li>Azeite</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Descasque as cenouras, a batata e a cebola. Leve a cozer num tacho com água e sal por 20 minutos.</li><li><b>Creme:</b> Adicione o gengibre fresco ralado e triture os legumes com a varinha mágica até obter um puré aveludado.</li><li><b>Finalizar:</b> Junte um fio de azeite em cru, mexa bem e sirva a sopa quente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_COGUMELOS_SALTEADOS + "', '<h3>Ingredientes:</h3><ul><li>250 g de cogumelos frescos laminados</li><li>2 dentes de alho picados</li><li>Azeite e salsa picada</li></ul><h3>Preparação:</h3><ol><li><b>Alho:</b> Aqueça um fio de azeite numa frigideira larga e doure o alho picado sem deixar queimar.</li><li><b>Saltear:</b> Adicione os cogumelos laminados em lume forte e deixe cozinhar até perderem a água e dourarem.</li><li><b>Finalizar:</b> Tempere com uma pitada de sal e polvilhe com bastante salsa fresca picada antes de retirar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SOPA_FEIJAO_VERDE + "', '<h3>Ingredientes:</h3><ul><li>150 g de feijão verde limpo</li><li>2 batatas e 1 cenoura</li><li>1 cebola média</li><li>Azeite e sal</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Coza as batatas, a cenoura e a cebola em água. Triture tudo até formar a base cremosa da sopa.</li><li><b>Pedaços:</b> Corte o feijão verde em tiras finas e adicione ao creme de legumes obtido.</li><li><b>Apurar:</b> Leve novamente ao lume por mais 10 minutos até o feijão verde estar cozido. Finalize com o azeite.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_CREME_BROCOLOS_QUEIJO + "', '<h3>Ingredientes:</h3><ul><li>1 cabeça de brócolos média</li><li>1 batata grande</li><li>1 cebola</li><li>50 g de queijo ralado magro e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Cozedura:</b> Corte os brócolos, a batata e a cebola em pedaços e leve a cozer num tacho com água e sal por 15 minutos.</li><li><b>Processar:</b> Triture a sopa com a varinha mágica até ficar cremosa e uniforme.</li><li><b>Queijo:</b> Incorpore o queijo ralado e o azeite no creme quente, mexendo em lume brando até o queijo derreter.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SALADA_RUSSA_VEG + "', '<h3>Ingredientes:</h3><ul><li>2 batatas e 1 cenoura grande</li><li>1/2 chávena de ervilhas</li><li>3 colheres de sopa de maionese vegetal</li></ul><h3>Preparação:</h3><ol><li><b>Cubos:</b> Descasque as batatas e a cenoura e corte-as em cubos pequenos e regulares.</li><li><b>Cozer:</b> Coza os cubos de legumes e as ervilhas em água com sal até ficarem macios mas firmes.</li><li><b>Arrefecer:</b> Escorra os legumes, deixe arrefecer completamente e envolva delicadamente na maionese vegetal.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SOPA_LEGUMES_EPOCA + "', '<h3>Ingredientes:</h3><ul><li>1/4 de abóbora e 1 nabo</li><li>1 cenoura e 1 chávena de nabiças cortadas</li><li>Azeite e sal</li></ul><h3>Preparação:</h3><ol><li><b>Creme:</b> Coza a abóbora, o nabo e a cenoura. Triture tudo com a varinha mágica até obter uma base lisa.</li><li><b>Verdes:</b> Junte as nabiças bem lavadas e cortadas ao creme e leve de novo ao lume por mais 8 minutos.</li><li><b>Servir:</b> Retifique o sal se necessário, adicione o fio de azeite e sirva bem quente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_OMELETE_ESPINAFRES + "', '<h3>Ingredientes:</h3><ul><li>2 ovos inteiros</li><li>1 chávena de espinafres frescos</li><li>1 dente de alho picado</li><li>Azeite e sal</li></ul><h3>Preparação:</h3><ol><li><b>Espinafres:</b> Salteie os espinafres com o alho picado e um fio de azeite numa frigideira até murcharem. Escorra.</li><li><b>Bater:</b> Bata os ovos com uma pitada de sal, junte os espinafres e verta na frigideira antiaderente quente.</li><li><b>Cozinhar:</b> Quando a base firmar, dobre a omelete ao meio e deixe dourar ligeiramente de ambos os lados.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_CREME_ABOBORA_SEMENTES + "', '<h3>Ingredientes:</h3><ul><li>400 g de abóbora limpa</li><li>1 cebola média</li><li>2 colheres de sopa de sementes de abóbora</li><li>Azeite</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Coloque a abóbora e a cebola cortadas em pedaços num tacho com água suficiente para cobrir os legumes.</li><li><b>Triturar:</b> Deixe cozer bem e reduza a puré. Junte um fio de azeite em cru e envolva na sopa quente.</li><li><b>Topping:</b> Sirva nos pratos e salpique a superfície com as sementes de abóbora previamente tostadas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_GASPACHO_MORANGO + "', '<h3>Ingredientes:</h3><ul><li>3 tomates maduros carnudos</li><li>1 de chávena de morangos limpos</li><li>1/2 pepino, azeite e vinagre</li></ul><h3>Preparação:</h3><ol><li><b>Processar:</b> No liquidificador, junte os tomates limpos, os morangos e o pepino cortados em pedaços.</li><li><b>Triturar:</b> Bata tudo muito bem até obter uma textura líquida e homogénea. Se preferir, passe por um coador.</li><li><b>Temperar:</b> Adicione o azeite, o vinagre e uma pitada de sal. Guarde no frigorífico para servir bem fresco.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SOPA_LENTILHAS_VERMELHAS + "', '<h3>Ingredientes:</h3><ul><li>1/2 de chávena de lentilhas vermelhas</li><li>1 cenoura e 1 cebola</li><li>Azeite e uma pitada de cominhos</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Leve a cozer as lentilhas vermelhas, a cenoura e a cebola em água abundante durante cerca de 15 minutos.</li><li><b>Creme:</b> Triture todos os ingredientes com a varinha mágica até obter um creme reconfortante e aveludado.</li><li><b>Tempero:</b> Adicione o azeite e uma pitada de cominhos em pó, mexendo bem antes de apagar o lume.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SALADA_GREGA_PEPINO + "', '<h3>Ingredientes:</h3><ul><li>1 pepino com casca</li><li>1 tomate grande maduro</li><li>50 g de queijo feta em cubos</li><li>Azeitonas pretas, azeite e orégãos</li></ul><h3>Preparação:</h3><ol><li><b>Cortar:</b> Corte o pepino e o tomate em pedaços médios e coloque-os diretamente numa taça.</li><li><b>Adicionar:</b> Distribua os cubos de queijo feta e as azeitonas por cima do preparado de vegetais.</li><li><b>Finalizar:</b> Tempere generosamente com azeite virgem extra e polvilhe com orégãos secos antes de envolver.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_CREME_COUVE_FLOR + "', '<h3>Ingredientes:</h3><ul><li>1/2 couve-flor média</li><li>1 batata pequena e 1 alho-francês</li><li>Uma pitada de noz-moscada</li><li>Azeite e sal</li></ul><h3>Preparação:</h3><ol><li><b>Cozedura:</b> Separe a couve-flor em floretes e coza-os com a batata e o alho-francês num tacho com água e sal.</li><li><b>Aveludar:</b> Triture com a varinha mágica até obter uma textura muito cremosa e esbranquiçada.</li><li><b>Especiaria:</b> Adicione um fio de azeite e uma pitada de noz-moscada ralada antes de servir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_TOFU_LIMAO + "', '<h3>Ingredientes:</h3><ul><li>150 g de tofu firme</li><li>Sumo de 1 limão</li><li>1 dente de alho picado</li><li>Azeite e coentros frescos</li></ul><h3>Preparação:</h3><ol><li><b>Marinar:</b> Corte o tofu em fatias finas e deixe marinar no sumo de limão e alho picado por 10 minutos.</li><li><b>Grelhar:</b> Aqueça o azeite numa frigideira e grelhe as fatias de tofu até ficarem bem douradas de ambos os lados.</li><li><b>Servir:</b> Coloque no prato, regue com o molho da frigideira e salpique com coentros frescos picados.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SOPA_GRAO_ESPINAFRES + "', '<h3>Ingredientes:</h3><ul><li>200 g de grão de bico cozido</li><li>1 cenoura grande</li><li>1 chávena de espinafres frescos</li><li>Azeite e sal</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Coza a cenoura e triture-a juntamente com metade do grão de bico e a água de cozedura.</li><li><b>Elementos:</b> Adicione o restante grão de bico inteiro e as folhas de espinafres frescos ao caldo obtido.</li><li><b>Cozinar:</b> Leve ao lume brando por mais 5 minutos até os espinafres murcharem. Adicione o azeite no final.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SALADA_RUCULA_PERA + "', '<h3>Ingredientes:</h3><ul><li>Folhas de rúcula selvagem</li><li>1 pera madura mas firme</li><li>30 g de nozes picadas</li><li>Azeite e sal</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Lave muito bem as folhas de rúcula e disponha-as como cama numa travessa.</li><li><b>Fruta:</b> Corte a pera em fatias finas com casca e distribua harmoniosamente sobre a rúcula.</li><li><b>Servir:</b> Salpique com as nozes picadas e tempere suavemente com um fio de azeite virgem extra.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_CREME_ERVILHAS + "', '<h3>Ingredientes:</h3><ul><li>300 g de ervilhas</li><li>1 batata e 1 cebola pequena</li><li>Azeite e sal</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Leve as ervilhas, a batata e a cebola cortada a cozer num tacho com água e sal durante 15 minutos.</li><li><b>Triturar:</b> Reduza a um creme verde brilhante e aveludado com a varinha mágica.</li><li><b>Finalizar:</b> Incorpore um fio de azeite em cru, retifique o tempero e sirva quente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_OVOS_TOMATE_SHAKSHUKA + "', '<h3>Ingredientes:</h3><ul><li>2 ovos inteiros</li><li>200 g de tomate pelado picado</li><li>1/2 cebola picada</li><li>Azeite e cominhos</li></ul><h3>Preparação:</h3><ol><li><b>Molho:</b> Salteie a cebola em azeite, adicione o tomate pelado e os cominhos. Deixe apurar por 8 minutos.</li><li><b>Ovos:</b> Abra pequenas cavidades no molho e verta os ovos lá dentro com cuidado para não romper a gema.</li><li><b>Estufar:</b> Tape a frigideira e deixe cozinhar em lume brando por 5 a 6 minutos até as claras firmarem.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SOPA_MINESTRONE_LEVE + "', '<h3>Ingredientes:</h3><ul><li>Cubos de vegetais (cenoura, curgete e aipo)</li><li>1/2 de chávena de feijão branco cozido</li><li>Polpa de tomate e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Refogado:</b> Faça uma base leve com cebola, azeite e os vegetais cortados em cubos muito pequenos.</li><li><b>Caldo:</b> Junte a polpa de tomate e água a ferver. Deixe cozinhar os legumes por 12 minutos.</li><li><b>Acabamento:</b> Adicione o feijão branco cozido e deixe apurar em lume brando por mais 3 minutos antes de servir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SALADA_BETERRABA_LARANJA + "', '<h3>Ingredientes:</h3><ul><li>1 beterraba cozida de tamanho médio</li><li>1 laranja doce</li><li>Folhas de alface fresca</li><li>Azeite e sal</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Corte a beterraba cozida em fatias finas ou cubos. Descasque a laranja e corte em gomos limpos.</li><li><b>Montagem:</b> Numa travessa, faça uma cama com a alface, disponha a beterraba e os gomos de laranja.</li><li><b>Tempero:</b> Regue tudo no momento de servir com um fio de azeite virgem extra e uma pitada de sal fino.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_CREME_COURGETTE_MANJERICO + "', '<h3>Ingredientes:</h3><ul><li>2 curgetes com pele</li><li>1 cebola</li><li>Folhas de manjericão fresco</li><li>Azeite e sal</li></ul><h3>Preparação:</h3><ol><li><b>Cozedura:</b> Lave muito bem as curgetes, corte em pedaços e junte à cebola num tacho com água e sal.</li><li><b>Ferver:</b> Deixe cozer por cerca de 15 a 20 minutos até os legumes estarem bem macios.</li><li><b>Triturar:</b> Use a varinha mágica até obter um creme. Junte o azeite e as folhas de manjericão fresco antes de servir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_PORTOBELLO_GRELHADO + "', '<h3>Ingredientes:</h3><ul><li>1 cogumelo Portobello grande</li><li>1 dente de alho picado</li><li>Azeite e sal</li><li>Folhas verdes para acompanhar</li></ul><h3>Preparação:</h3><ol><li><b>Cogumelo:</b> Limpe o cogumelo com papel húmido, retire o talo e tempere o chapéu com o alho picado e sal.</li><li><b>Grelhar:</b> Coloque o Portobello numa grelha quente com azeite, cozinhando cerca de 4 minutos de cada lado.</li><li><b>Empratar:</b> Sirva o cogumelo fatiado quente ao lado de uma salada fresca de folhas verdes temperada com azeite.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SOPA_TOMATE_ARROZ + "', '<h3>Ingredientes:</h3><ul><li>3 tomates maduros picados</li><li>1 cebola</li><li>2 colheres de sopa de arroz</li><li>Azeite e sal</li></ul><h3>Preparação:</h3><ol><li><b>Refogado:</b> Refogue a cebola picada em azeite, junte os tomates limpos e deixe estufar até ficarem macios.</li><li><b>Caldo:</b> Verta água a ferver, tempere com uma pitada de sal e adicione as colheres de arroz.</li><li><b>Cozedura:</b> Deixe cozinhar em lume brando por 15 minutos até o arroz estar tenro e abraçado ao caldo de tomate.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SALADA_ALFACE_MILHO_ABACATE + "', '<h3>Ingredientes:</h3><ul><li>Folhas de alface variadas</li><li>1/2 abacate maduro em cubos</li><li>1/2 de chávena de milho doce escorrido</li><li>Azeite</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Lave e corte as folhas de alface, colocando-as no fundo de uma saladeira média.</li><li><b>Juntar:</b> Adicione o milho doce escorrido e os cubos de abacate fresco sobre as folhas.</li><li><b>Tempero:</b> Misture tudo levemente e regue com um fio de azeite virgem extra no momento de servir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_CREME_ESPARGOS_VERDES + "', '<h3>Ingredientes:</h3><ul><li>1 molho de espargos verdes</li><li>1 batata pequena e 1 cebola</li><li>Azeite e sal</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Elimine a base lenhosa e mais dura dos espargos. Corte os talos restantes em pedaços pequenos.</li><li><b>Cozer:</b> Leve os pedaços de espargos, a batata e a cebola a cozer num tacho com água e sal por 15 minutos.</li><li><b>Triturar:</b> Use a varinha mágica para reduzir tudo a um creme verde sedoso e finalize com o azeite.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_TOFU_MEXIDO_ERVAS + "', '<h3>Ingredientes:</h3><ul><li>150 g de tofu firme</li><li>1 colher de chá de misto de ervas aromáticas secas</li><li>Azeite e sal</li></ul><h3>Preparação:</h3><ol><li><b>Esmagar:</b> Com a ajuda de um garfo, esmague o bloco de tofu numa taça até obter migalhas grossas.</li><li><b>Cozinhar:</b> Salteie o tofu numa frigideira com azeite e o misto de ervas aromáticas secas.</li><li><b>Finalizar:</b> Mexa bem por 5 minutos em lume brando até o tofu perder a humidade e ganhar os sabores das ervas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SOPA_CEBOLA + "', '<h3>Ingredientes:</h3><ul><li>3 cebolas grandes em rodelas finas</li><li>500 ml de caldo de vegetais</li><li>1 colher de sopa de azeite</li><li>Sal e pimenta</li></ul><h3>Preparação:</h3><ol><li><b>Caramelizar:</b> Cozinhe as rodelas de cebola no azeite em lume muito brando até ficarem douradas e muito macias.</li><li><b>Caldo:</b> Verta o caldo de vegetais quente sobre as cebolas e tempere com uma pitada de sal.</li><li><b>Ferver:</b> Deixe a sopa ferver tapada por cerca de 15 minutos para apurar todos os sabores.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_APR_SALADA_GRAO_CHERRY + "', '<h3>Ingredientes:</h3><ul><li>200 g de grão de bico cozido escorrido</li><li>1 de chávena de tomates cherry</li><li>Azeite, salsa e orégãos</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Enxague o grão de bico cozido e coloque-o diretamente numa saladeira profunda.</li><li><b>Juntar:</b> Adicione os tomates cherry cortados ao meio e uma boa quantidade de salsa fresca picada.</li><li><b>Tempero:</b> Regue generosamente com um bom azeite virgem extra e polvilhe com orégãos secos antes de envolver.</li></ol>');");

