// PEQUENOS-ALMOÇOS - MAIO (TODOS OS 31 DIAS)
// ==========================================

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SMOOTHIE_ANANAS_COCO + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de ananás em cubos</li><li>200 ml de leite de coco leve</li><li>1 colher de sopa de coco ralado</li></ul><h3>Preparação:</h3><ol><li><b>Triturar:</b> Coloque os cubos de ananás frescos e o leite de coco leve no copo do liquidificador.</li><li><b>Bater:</b> Processe tudo na velocidade máxima até obter um batido sedoso. Sirva polvilhado com o coco ralado por cima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_AVEIA_MORANGO + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de sopa de flocos de aveia</li><li>250 ml de água ou leite magro</li><li>4 morangos frescos fatiados</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Junte os flocos de aveia e o líquido num tacho pequeno. Leve ao lume brando, mexendo sempre até criar consistência.</li><li><b>Servir:</b> Transfira as papas para uma taça e distribua as fatias de morangos lavados pela superfície.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_TORRADA_ABACATE_RABANETE + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão integral de centeio</li><li>1/2 abacate maduro</li><li>2 rabanetes cortados em rodelas finas</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Toste a fatia de pão de centeio na torradeira até ficar bem estaladiça.</li><li><b>Montar:</b> Esmague o abacate com um garfo sobre o pão e disponha as rodelas de rabanete por cima para dar um toque picante e crocante.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_PUDIM_CHIA_ANANAS + "', '<h3>Ingredientes:</h3><ul><li>3 colheres de sopa de sementes de chia</li><li>200 ml de bebida de amêndoa</li><li>1 rodela grossa de ananás em cubos</li></ul><h3>Preparação:</h3><ol><li><b>Gelatinar:</b> Misture as sementes de chia com a bebida de amêndoa numa taça e deixe repousar no frigorífico durante a noite.</li><li><b>Fruta:</b> Na manhã seguinte, remexa o pudim espesso e adicione os cubos de ananás fresco no topo antes de consumir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_PANQUECAS_MIRTILO_LIMAO + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de farinha de aveia</li><li>1 ovo médio e 100 ml de leite</li><li>Raspas de limão e um punhado de mirtilos</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Misture a farinha, o ovo, o leite e as raspas de limão até criar uma massa homogénea. Envolva os mirtilos inteiros.</li><li><b>Cozinhar:</b> Deite porções da massa numa frigideira antiaderente quente e vire quando dourarem de ambos os lados.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SMOOTHIE_BOWL_VERDE + "', '<h3>Ingredientes:</h3><ul><li>1 banana previamente congelada</li><li>1 chávena de folhas de espinafres novos</li><li>100 ml de bebida vegetal à escolha</li></ul><h3>Preparação:</h3><ol><li><b>Bater:</b> Coloque no liquidificador a banana congelada em rodelas, os espinafres bem lavados e o líquido.</li><li><b>Textura:</b> Triture até conseguir um creme verde muito espesso e transfira para uma taça profunda para comer com colher.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_TACA_IOGURTE_KIWI + "', '<h3>Ingredientes:</h3><ul><li>1 iogurte natural ou vegetal</li><li>1 kiwi maduro fatiado</li><li>1 colher de sopa de sementes de girassol</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Coloque o iogurte natural no fundo de uma taça ou copo largo.</li><li><b>Finalizar:</b> Disponha as fatias de kiwi fresco por cima e salpique com as sementes de girassol para criar textura.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_TORRADA_MANTEIGA_AMENDOIM_MORANGO + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão de sementes rústico</li><li>1 colher de sopa de manteiga de amendoim pura</li><li>3 morangos lavados e fatiados</li></ul><h3>Preparação:</h3><ol><li><b>Tostar:</b> Coloque a fatia de pão a tostar na torradeira ao seu gosto.</li><li><b>Barrar:</b> Espalhe a manteiga de amendoim sobre o pão morno e decore com as fatias de morango por cima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_MEXIDO_TOFU_TOMATE_CHERRY + "', '<h3>Ingredientes:</h3><ul><li>150 g de tofu firme esmagado</li><li>5 tomates cherry cortados ao meio</li><li>Azeite e uma pitada de curcuma</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Numa frigideira com um fio de azeite, salteie os tomates cherry até começarem a amolecer.</li><li><b>Cozinhar:</b> Junte o tofu esmagado com o garfo e a curcuma. Mexa continuamente em lume médio durante 5 minutos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_AVEIA_COCO_MANGA + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de sopa de flocos de aveia</li><li>200 ml de leite de coco leve</li><li>1/2 manga madura cortada em cubos</li></ul><h3>Preparação:</h3><ol><li><b>Cozedura:</b> Leve os flocos de aveia e o leite de coco ao lume, mexendo até atingir uma consistência cremosa.</li><li><b>Acompanhar:</b> Verta para uma taça e junte os cubos de manga fresca na superfície antes de servir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SMOOTHIE_FRAMBOESA_BANANA + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de framboesas frescas ou congeladas</li><li>1 banana madura</li><li>200 ml de bebida de aveia</li></ul><h3>Preparação:</h3><ol><li><b>Processar:</b> Junte as framboesas, a banana e a bebida de aveia no copo do seu liquidificador.</li><li><b>Bater:</b> Triture na velocidade máxima durante 1 minuto até obter um batido cremoso de tom rosado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_PANQUECAS_AVEIA_MEL + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de farinha de aveia integral</li><li>1 ovo e 100 ml de leite ou bebida de arroz</li><li>1 colher de sobremesa de mel silvestre</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Misture a farinha de aveia, o ovo e a bebida vegetal com um batedor até eliminar todos os grumos.</li><li><b>Grelhar:</b> Cozinhe porções da massa numa frigideira antiaderente. Sirva as panquecas quentes com o fio de mel por cima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_TORRADA_HUMUS_TOMATE + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão de mistura alentejano</li><li>2 colheres de sopa de húmus de grão</li><li>1/2 tomate maduro em fatias</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Toste a fatia de pão até dourar ligeiramente de ambos os lados.</li><li><b>Montagem:</b> Barre o húmus de grão generosamente no pão e cubra com as fatias de tomate fresco.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_MUESLI_FRUTOS_VERMELHOS + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de sopa de muesli tradicional</li><li>150 ml de iogurte natural</li><li>Mistura de frutos vermelhos frescos (amoras, framboesas)</li></ul><h3>Preparação:</h3><ol><li><b>Combinar:</b> Numa taça larga, coloque o muesli e envolva suavemente com o iogurte natural.</li><li><b>Fruta:</b> Decore o topo com a mistura de frutos vermelhos frescos bem lavados antes de consumir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_PAPA_QUINOA_MACA + "', '<h3>Ingredientes:</h3><ul><li>1/2 de chávena de quinoa previamente cozida</li><li>1/2 maçã ralada</li><li>100 ml de leite vegetal e canela</li></ul><h3>Preparação:</h3><ol><li><b>Aquecer:</b> Num tacho pequeno, misture a quinoa cozida, a maçã ralada e o leite vegetal.</li><li><b>Apurar:</b> Deixe cozinhar em lume brando por 5 minutos até fundir os sabores e polvilhe com canela em pó.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SMOOTHIE_MANGA_LIMA + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de cubos de manga madura</li><li>Sumo de 1/2 lima fresca</li><li>200 ml de água de coco</li></ul><h3>Preparação:</h3><ol><li><b>Liquidificar:</b> Coloque os cubos de manga, o sumo da lima espremido na hora e a água de coco no liquidificador.</li><li><b>Bater:</b> Processe tudo muito bem até obter um sumo cremoso, refrescante e cítrico.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_TORRADA_ABACATE_OVO_ESCALFADO + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão de cereais integral</li><li>1/2 abacate maduro esmagado</li><li>1 ovo escalfado</li></ul><h3>Preparação:</h3><ol><li><b>Tostar:</b> Comece por tostar a sua fatia de pão de cereais integral na torradeira.</li><li><b>Finalizar:</b> Barre o abacate com um garfo no pão e coloque cuidadosamente o ovo escalfado quente no topo.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_TACA_ACAI_GRANOLA + "', '<h3>Ingredientes:</h3><ul><li>100 g de polpa de açaí congelada</li><li>1 banana pequena em rodelas</li><li>3 colheres de sopa de granola caseira</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Triture a polpa de açaí com metade da banana até formar um creme gelado espesso.</li><li><b>Servir:</b> Verta numa taça e decore o topo com a granola e as restantes rodelas de banana.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_PAPAS_MILHO_DOCE + "', '<h3>Ingredientes:</h3><ul><li>3 colheres de sopa de sêmola de milho</li><li>250 ml de bebida de aveia</li><li>1 colher de chá de xarope de agave</li></ul><h3>Preparação:</h3><ol><li><b>Ferver:</b> Aqueça a bebida de aveia num tacho pequeno até começar a levantar fervura.</li><li><b>Engrossar:</b> Junte a sêmola de milho e cozinhe em lume brando, mexendo até espessar. Adoce com o agave.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SMOOTHIE_BOWL_MORANGO + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de morangos congelados</li><li>1 banana madura</li><li>50 ml de leite de amêndoa</li></ul><h3>Preparação:</h3><ol><li><b>Creme:</b> Coloque os morangos congelados, a banana e o leite de amêndoa no processador ou liquidificador.</li><li><b>Bater:</b> Processe lentamente até obter um creme gelado e homogéneo. Transfira para uma taça profunda.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_AVEIA_ANANAS_HORTELA + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de sopa de flocos de aveia</li><li>250 ml de água</li><li>1 rodela de ananás fresco picado e 3 folhas de hortelã</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Leve os flocos de aveia ao lume com a água até formar uma papa aveludada.</li><li><b>Frescura:</b> Retire do lume, incorpore os pedaços de ananás fresco e guarneça com as folhas de hortelã picadas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_PANQUECAS_BANANA_CANELA + "', '<h3>Ingredientes:</h3><ul><li>1 banana média bem madura</li><li>1 ovo inteiro</li><li>2 colheres de sopa de farinha de aveia e canela</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Esmague a banana na totalidade, misture com o ovo, a aveia e uma pitada generosa de canela em pó.</li><li><b>Cozinhar:</b> Coza pequenas porções de massa numa frigideira antiaderente bem quente até dourarem de ambos os lados.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_TORRADA_QUEIJO_FRESCO_TOMATE + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão integral rústico</li><li>1 queijo fresco pequeno magro</li><li>2 fatias de tomate maduro</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Toste a fatia de pão na torradeira até ficar estaladiça.</li><li><b>Montar:</b> Disponha as fatias de queijo fresco e de tomate por cima do pão quente e tempere com orégãos secos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_IOGURTE_GRANOLA_MIRTILO + "', '<h3>Ingredientes:</h3><ul><li>1 iogurte natural denso</li><li>3 colheres de sopa de granola de cereais</li><li>Um punhado de mirtilos frescos</li></ul><h3>Preparação:</h3><ol><li><b>Montar:</b> Coloque o iogurte natural denso numa taça média de pequeno-almoço.</li><li><b>Toppings:</b> Adicione a granola de um dos lados e distribua os mirtilos lavados pelo lado restante antes de servir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SMOOTHIE_ESPINAFRE_MACA + "', '<h3>Ingredientes:</h3><ul><li>1 maçã verde com casca picada</li><li>1 chávena de folhas de espinafres novos</li><li>200 ml de água fresca</li></ul><h3>Preparação:</h3><ol><li><b>Processar:</b> Junte os cubos de maçã verde, as folhas de espinafres limpas e a água no copo do liquidificador.</li><li><b>Bater:</b> Triture na velocidade máxima até os ingredientes ficarem desfeitos num sumo uniforme.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_PUDIM_CHIA_MANGA_COCO + "', '<h3>Ingredientes:</h3><ul><li>3 colheres de sopa de sementes de chia</li><li>200 ml de leite de coco leve</li><li>1/2 manga madura reduzida a puré</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Misture as sementes de chia com o leite de coco numa taça e guarde no frigorífico durante a noite.</li><li><b>Finalizar:</b> Na manhã seguinte, coloque o puré de manga fresca por cima do pudim gelatinoso antes de comer.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_TORRADA_ABACATE_PIMENTAO + "', '<h3>Ingredientes:</h3><ul><li>1 fatia grande de pão rústico</li><li>1/2 abacate maduro</li><li>Uma pitada de pimentão doce em pó (paprica)</li></ul><h3>Preparação:</h3><ol><li><b>Tostar:</b> Grelhe ou toste a sua fatia de pão rústico na torradeira.</li><li><b>Barrar:</b> Esmague o abacate diretamente no pão e salpique a superfície com uma pitada leve de pimentão doce.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_AVEIA_CHOCOLATE_MORANGO + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de sopa de flocos de aveia</li><li>250 ml de leite magro ou bebida de aveia</li><li>1 colher de chá de cacau em pó puro e morangos</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Leve a aveia, o leite e o cacau em pó ao lume, mexendo sempre até a mistura engrossar.</li><li><b>Decorar:</b> Transfira para uma taça e decore a superfície com morangos frescos fatiados.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SMOOTHIE_SILVESTRE_LINHACA + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de frutos silvestres mistos</li><li>1 colher de sopa de sementes de linhaça moídas</li><li>200 ml de bebida vegetal</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Insira as bagas silvestres, a linhaça moída e a bebida vegetal escolhida no liquidificador.</li><li><b>Bater:</b> Processe tudo na velocidade máxima durante 1 minuto até obter um batido homogéneo e encorpado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_PANQUECAS_INTEGRAIS_FRUTA + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de farinha de trigo integral</li><li>1 ovo médio e 150 ml de leite</li><li>Pedaços de fruta da época para acompanhar</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Envolva energeticamente a farinha integral, o ovo e o leite com uma vara de arames até ligar bem.</li><li><b>Cozer:</b> Deite porções em pequenas rodelas numa frigideira quente e doure. Sirva acompanhado com a fruta fresca.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_TACA_IOGURTE_MEL_NOZES + "', '<h3>Ingredientes:</h3><ul><li>1 iogurte grego natural magro</li><li>1 colher de sobremesa de mel líquido</li><li>4 nozes picadas com as mãos</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Verta o iogurte grego natural numa taça individual de sobremesa.</li><li><b>Finalizar:</b> Adicione o mel em fio por cima do iogurte e espalhe os pedaços de nozes crocantes.</li></ol>');");

        // ==========================================
// ALMOÇOS - MAIO (31 DIAS)
// ==========================================

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_CARIL_GRAO_ESPINAFRES + "', '<h3>Ingredientes:</h3><ul><li>Grão-de-bico, espinafres frescos, leite de coco</li><li>Caril, cebola, alho</li></ul><h3>Preparação:</h3><ol><li><b>Refogar:</b> A cebola e o alho.</li><li><b>Cozinhar:</b> Juntar o grão e o leite de coco com caril.</li><li><b>Finalizar:</b> Adicionar os espinafres no fim para murcharem ligeiramente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SALADA_QUINOA_TROPICAL + "', '<h3>Ingredientes:</h3><ul><li>Quinoa, manga, abacate, coentros</li><li>Lima, azeite</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Cozer a quinoa e deixar arrefecer.</li><li><b>Misturar:</b> Envolver com a fruta em cubos.</li><li><b>Temperar:</b> Com sumo de lima e azeite.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_MASSA_PRIMAVERA + "', '<h3>Ingredientes:</h3><ul><li>Massa integral, espargos, ervilhas, curgete</li><li>Azeite, limão, hortelã</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> A massa al dente.</li><li><b>Saltear:</b> Os vegetais rapidamente em azeite.</li><li><b>Envolver:</b> Misturar tudo com raspa de limão e hortelã.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_CHILI_VEGETARIANO_LEVE + "', '<h3>Ingredientes:</h3><ul><li>Feijão preto, milho, tomate, cominhos</li><li>Pimento, cebola</li></ul><h3>Preparação:</h3><ol><li><b>Estufar:</b> Refogar vegetais e juntar feijão e tomate.</li><li><b>Temperar:</b> Com bastante cominhos e picante.</li><li><b>Servir:</b> Acompanhado de arroz integral.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_RISOTO_COGUMELOS_ERVAS + "', '<h3>Ingredientes:</h3><ul><li>Arroz arbório, cogumelos frescos</li><li>Caldo vegetal, ervas frescas</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Adicionar o caldo gradualmente ao arroz.</li><li><b>Finalizar:</b> Juntar os cogumelos salteados e muitas ervas frescas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SALADA_LENTILHAS_FETA + "', '<h3>Ingredientes:</h3><ul><li>Lentilhas, queijo feta, tomate cherry</li><li>Pepino, cebola roxa</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> As lentilhas.</li><li><b>Montar:</b> Misturar com vegetais frescos.</li><li><b>Finalizar:</b> Adicionar o queijo feta esfarelado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_TORTILHA_ESPINAFRES_COGUMELOS + "', '<h3>Ingredientes:</h3><ul><li>Base ovo vegetal, espinafres, cogumelos</li><li>Alho, azeite</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Espinafres e cogumelos.</li><li><b>Cozer:</b> Juntar a base de ovo e cozinhar em lume brando até firmar.</li></ol>');");

