        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_MASSA_PESTO_TOMATE_CHERRY + "', '<h3>Ingredientes:</h3><ul><li>Massa, pesto de manjericão, tomate</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Massa.</li><li><b>Envolver:</b> No pesto e adicionar tomates cortados.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_GRATINADO_LEGUMES_PRIMAVERA + "', '<h3>Ingredientes:</h3><ul><li>Brócolos, cenoura, couve-flor</li><li>Molho branco, queijo ralado</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Legumes brevemente.</li><li><b>Assar:</b> No forno com o molho e queijo.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SALADA_LENTILHAS_MACA_NOZ + "', '<h3>Ingredientes:</h3><ul><li>Lentilhas, maçã fatiada, nozes</li><li>Vinagrete de mel</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Lentilhas.</li><li><b>Montar:</b> Com fatias finas de maçã e nozes picadas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_RISOTO_ABOBORA_NOZ_MOSCADA + "', '<h3>Ingredientes:</h3><ul><li>Arroz arbório, puré de abóbora</li><li>Noz-moscada, caldo</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Arroz com caldo.</li><li><b>Finalizar:</b> Com puré de abóbora e noz-moscada.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_CANELONES_RICOTA_ESPINAFRES + "', '<h3>Ingredientes:</h3><ul><li>Massa de canelone, ricota, espinafres</li><li>Molho de tomate</li></ul><h3>Preparação:</h3><ol><li><b>Rechear:</b> Massa.</li><li><b>Assar:</b> Com molho de tomate no forno.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SALADA_QUINOA_MANGA_AMENDOA + "', '<h3>Ingredientes:</h3><ul><li>Quinoa, manga, amêndoa laminada</li><li>Lima</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Quinoa.</li><li><b>Misturar:</b> Fruta e frutos secos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_CARIL_VEGETAIS_COCO_LEVE + "', '<h3>Ingredientes:</h3><ul><li>Mix de vegetais, leite de coco</li><li>Caril suave</li></ul><h3>Preparação:</h3><ol><li><b>Estufar:</b> Legumes com caril e leite de coco.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SALTEADO_TOFU_LEGUMES_CROCANTES + "', '<h3>Ingredientes:</h3><ul><li>Tofu, pimentos, brócolos, cenoura</li><li>Molho de soja</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Tudo em lume alto.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SOPA_TOMATE_OVO_ESCALFADO + "', '<h3>Ingredientes:</h3><ul><li>Sopa de tomate, base de ovo vegetal</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Sopa.</li><li><b>Finalizar:</b> Cozer o ovo diretamente na sopa.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SALADA_MACARRAO_PESTO_RUCULA + "', '<h3>Ingredientes:</h3><ul><li>Massa, pesto, rúcula fresca</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Massa com pesto.</li><li><b>Servir:</b> Sobre cama de rúcula.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_EMPADAO_VEGETARIANO_LENTILHAS + "', '<h3>Ingredientes:</h3><ul><li>Lentilhas estufadas, puré de batata</li></ul><h3>Preparação:</h3><ol><li><b>Montar:</b> Lentilhas por baixo.</li><li><b>Assar:</b> Puré por cima no forno.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_PAELLA_VEGETARIANA_PRIMAVERA + "', '<h3>Ingredientes:</h3><ul><li>Arroz, ervilhas, espargos, açafrão</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Estilo paella com legumes frescos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_MAY_SALADA_GRAO_MEDITERRANICA + "', '<h3>Ingredientes:</h3><ul><li>Grão, tomate, pepino, azeitonas</li><li>Orégãos</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Todos os ingredientes.</li><li><b>Temperar:</b> Com bom azeite.</li></ol>');");

        // ==========================================
