        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_PAPA_AVEIA_MACA_CANELA_FORNO + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de sopa de aveia em flocos</li><li>1 maçã média picada em cubos</li><li>1 colher de chá de canela e leite vegetal</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Junte a aveia, os cubos de maçã, a canela e cobrindo com o leite vegetal numa taça própria.</li><li><b>Assar:</b> Leve a taça ao forno pré-aquecido até criar uma crosta dourada e a maçã ficar completamente macia.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_TORRADA_MANTEIGA_AVELA_FIGO_CALDA + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão integral de sementes</li><li>1 colher de sopa de manteiga de avelã</li><li>1 figo fresco fatiado em calda leve</li></ul><h3>Preparação:</h3><ol><li><b>Torrar:</b> Coloque a fatia de pão integral na torradeira até atingir uma consistência bem estaladiça.</li><li><b>Montar:</b> Barre a superfície com a manteiga de avelã cremosa e disponha as fatias de figo por cima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_PANQUECA_ABOBORA_ESPECIARIAS + "', '<h3>Ingredientes:</h3><ul><li>3 colheres de sopa de puré de abóbora</li><li>1 ovo inteiro fresco</li><li>2 colheres de aveia e uma pitada de canela</li></ul><h3>Preparação:</h3><ol><li><b>Bater:</b> Envolva o puré de abóbora com o ovo, a aveia e a canela numa tigela até formar um creme liso.</li><li><b>Cozinhar:</b> Verta porções da massa numa frigideira antiaderente quente e doure ligeiramente de ambos os lados.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_BATIDO_OUTONO_PERA_ROCHA_NOZ + "', '<h3>Ingredientes:</h3><ul><li>1 pera rocha média e madura</li><li>3 nozes inteiras descascadas</li><li>1 chávena de bebida de aveia bem fresca</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Lave bem a pera rocha, limpe as sementes do interior e corte a polpa em pedaços pequenos.</li><li><b>Triturar:</b> Coloque a fruta, as nozes e a bebida de aveia no liquidificador e processe na velocidade máxima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_TACA_IOGURTE_UVAS_VINDIMA_GRANOLA + "', '<h3>Ingredientes:</h3><ul><li>1 embalagem de iogurte vegetal natural</li><li>1/2 chávena de uvas pretas doces</li><li>2 colheres de sopa de granola caseira</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Deite o iogurte vegetal natural diretamente no fundo de uma taça larga de pequeno-almoço.</li><li><b>Topping:</b> Lave as uvas, corte-as ao meio e distribua sobre o iogurte juntamente com a granola crocante.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_PUDIM_CHIA_ROMA_SABUGUEIRO + "', '<h3>Ingredientes:</h3><ul><li>2 colheres de sopa de sementes de chia</li><li>1/2 chávena de leite de amêndoa</li><li>Bagas de romã e 1 colher de xarope de sabugueiro</li></ul><h3>Preparação:</h3><ol><li><b>Gelificar:</b> Misture a chia com o leite e o xarope, deixando repousar no frigorífico por quatro horas.</li><li><b>Finalizar:</b> Retire o pudim firme do frio e adicione as bagas frescas de romã por cima antes de comer.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_TORRADA_RICOTA_PERA_GRELHADA_MEL + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão de centeio torrado</li><li>2 colheres de sopa de queijo ricota leve</li><li>1/2 de pera rocha fatiada e um fio de mel</li></ul><h3>Preparação:</h3><ol><li><b>Grelhar:</b> Coloque as fatias de pera numa frigideira bem quente até dourarem ligeiramente de ambos os lados.</li><li><b>Barrar:</b> Cubra o pão com o queijo ricota, disponha a pera grelhada e finalize vertendo um fio de mel puro.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_MUFFIN_INTEGRAL_ALFARROBA_NOZ + "', '<h3>Ingredientes:</h3><ul><li>3 colheres de farinha integral e 1 de alfarroba</li><li>1 ovo inteiro e 2 nozes picadas</li><li>1 colher de chá de fermento em pó</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Misture os secos, envolva o ovo batido e adicione as nozes picadas até criar uma pasta homogénea.</li><li><b>Assar:</b> Deite o preparado em formas de silicone e leve ao forno a cozer durante cerca de quinze minutos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_MEXIDO_TOFU_ESPINAFRE_ALHO_PORRO + "', '<h3>Ingredientes:</h3><ul><li>100 g de tofu firme amassado</li><li>1/2 chávena de espinafres limpos</li><li>1/4 de alho-francês fatiado em rodelas</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Cozinhe o alho-francês e os espinafres numa frigideira antiaderente com um pequeno fio de azeite.</li><li><b>Mexer:</b> Adicione o tofu bem amassado com um garfo, envolva nos legumes e cozinhe por cinco minutos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_PAPA_ARROZ_INTEGRAL_COCO_LARANJA + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de arroz integral cozido simples</li><li>1/2 chávena de leite de coco leve</li><li>Raspa de casca de laranja fresca</li></ul><h3>Preparação:</h3><ol><li><b>Cozzer:</b> Leve o arroz integral cozido ao lume com o leite de coco e as raspas finas de casca de laranja.</li><li><b>Apurar:</b> Deixe ferver lentamente mexendo sempre até obter uma consistência muito cremosa e aveludada.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_CREPE_AVEIA_CREME_CHOCOLATE_NEGRO + "', '<h3>Ingredientes:</h3><ul><li>1 ovo inteiro e 2 colheres de farinha de aveia</li><li>2 colheres de sopa de leite vegetal</li><li>1 quadrado de chocolate negro derretido</li></ul><h3>Preparação:</h3><ol><li><b>Crepe:</b> Bata o ovo com a aveia e o leite. Verta na frigideira e faça um crepe fino de ambos os lados.</li><li><b>Recheio:</b> Espalhe o chocolate negro derretido no interior do crepe quente, dobre ao meio e sirva.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_BOLO_CHAVENA_MACA_AMENDOA_MICROONDAS + "', '<h3>Ingredientes:</h3><ul><li>1 ovo fresco e 2 colheres de farinha de amêndoa</li><li>1/2 maçã madura finamente ralada</li><li>Uma pequena pitada de fermento</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Junte o ovo, a amêndoa, a maçã ralada e o fermento diretamente no interior de uma chávena.</li><li><b>Cozinhar:</b> Mexa energicamente com um garfo e leve ao micro-ondas em potência máxima por noventa segundos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_TORRADA_SMASH_GRAO_BICO_PIMENTA + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão rústico ou saloio</li><li>3 colheres de sopa de grão-de-bico cozido</li><li>Uma pitada de pimenta preta e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Esmagar:</b> Triture o grão-de-bico cozido com um garfo juntamente com um fio de azeite e a pimenta preta.</li><li><b>Servir:</b> Torre a fatia de pão rústico e espalhe esta pasta espessa e saborosa sobre a superfície quente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_BOLO_FRIGIDEIRA_BATATA_DOCE_NOZ + "', '<h3>Ingredientes:</h3><ul><li>2 colheres de sopa de puré de batata-doce</li><li>1 ovo inteiro e 1 colher de sopa de aveia</li><li>2 nozes picadas grosseiramente</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Misture muito bem o puré de batata-doce com o ovo, os flocos de aveia e as nozes picadas.</li><li><b>Cozzer:</b> Verta na frigideira antiaderente tapada e cozinhe em lume muito brando de ambos os lados.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_GRANOLA_QUENTE_BEBIDA_AVEIA_PASSA + "', '<h3>Ingredientes:</h3><ul><li>3 colheres de sopa de granola caseira</li><li>1/2 chávena de bebida de aveia bem quente</li><li>1 colher de sopa de passas de uva doces</li></ul><h3>Preparação:</h3><ol><li><b>Juntar:</b> Coloque a granola crocante e as passas de uva no fundo de uma taça média de pequeno-almoço.</li><li><b>Amolecer:</b> Verta a bebida de aveia bem quente por cima e deixe repousar dois minutos antes de consumir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_PUDIM_LINHACA_SABOR_TARTE_MACA + "', '<h3>Ingredientes:</h3><ul><li>2 colheres de sopa de sementes de linhaça moída</li><li>1/2 chávena de água morna e canela</li><li>1/2 maçã cozida esmagada com garfo</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Misture a linhaça com a água morna e a canela até criar um gel espesso em poucos minutos.</li><li><b>Cobrir:</b> Disponha a polpa de maçã cozida esmagada por cima para obter um delicioso sabor a tarte caseira.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_TORRADA_HUMUS_PIMENTOS_PADRON + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão de sementes torrado</li><li>2 colheres de sopa de húmus caseiro</li><li>3 pimentos padrón grelhados sem gordura</li></ul><h3>Preparação:</h3><ol><li><b>Barrar:</b> Aplique o húmus cremoso sobre a superfície da fatia de pão de sementes bem torrada.</li><li><b>Montar:</b> Disponha os pimentos padrón previamente grelhados inteiros por cima do húmus e sirva morno.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_BATIDO_ROXO_UVA_PRETA_SEMENTES + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de uvas pretas limpas e sem grainha</li><li>1 chávena de leite vegetal de arroz ou amêndoa</li><li>1 colher de sopa de sementes de girassol</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Insira as uvas pretas bem lavadas, as sementes de girassol e o leite vegetal no liquidificador.</li><li><b>Bater:</b> Triture todos os ingredientes na velocidade máxima até obter um batido roxo homogéneo.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_SCONES_ESPELTA_AROMA_ERVA_DOCE + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de farinha de espelta integral</li><li>2 colheres de sopa de iogurte natural leve</li><li>1 colher de chá de sementes de erva-doce</li></ul><h3>Preparação:</h3><ol><li><b>Amassar:</b> Envolva a farinha com o iogurte e as sementes de erva-doce até formar uma bola compacta de massa.</li><li><b>Forno:</b> Molde pequenos montinhos com as mãos e leve ao forno num tabuleiro até cozerem e dourarem.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_PAPA_PAINCO_COMPOTA_PERA_ROCHA + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de sopa de painço cozido simples</li><li>1/2 chávena de leite magro ou vegetal</li><li>1 colher de sopa de compota de pera rocha</li></ul><h3>Preparação:</h3><ol><li><b>Aquecer:</b> Aqueça o painço cozido com o leite num pequeno tacho até criar uma papa bem aveludada.</li><li><b>Finalizar:</b> Transfira para uma taça rasa e coloque a colher de compota de pera rocha no topo.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_BARRINHA_AVEIA_FORNO_ALFARROBA + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de sopa de flocos de aveia finos</li><li>1 colher de sopa de alfarroba em pó</li><li>1 colher de geleia de arroz e água</li></ul><h3>Preparação:</h3><ol><li><b>Pasta:</b> Misture a aveia, a alfarroba e a geleia com pouca água até obter uma pasta moldável densa.</li><li><b>Firmar:</b> Molde em formato de barra retangular e leve ao forno durante dez minutos para ganhar firmeza.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_TORRADA_CREME_AMENDOIM_MACA_QUENTE + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão integral de sementes</li><li>1 colher de sopa de creme de amendoim puro</li><li>1/2 maçã fatiada e aquecida no micro-ondas</li></ul><h3>Preparação:</h3><ol><li><b>Barrar:</b> Torre o pão e espalhe o creme de amendoim sobre a superfície quente de forma uniforme.</li><li><b>Cobrir:</b> Disponha as fatias de maçã amolecidas e quentes por cima do creme e consuma de imediato.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_BATIDO_VERDE_KALE_PERA_GENGIBRE + "', '<h3>Ingredientes:</h3><ul><li>1 folha de couve kale limpa e sem talo</li><li>1/2 pera rocha média com casca</li><li>Um pedaço pequeno de gengibre e água fria</li></ul><h3>Preparação:</h3><ol><li><b>Triturar:</b> Introduza a folha de kale, a pera em pedaços, o gengibre e a água fria no liquidificador.</li><li><b>Processar:</b> Misture na velocidade máxima até obter um batido verde totalmente homogéneo e liso.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_TACA_KEFIR_DOCE_FIGO_LINHACA + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de kefir natural fresco</li><li>1 figo fresco médio picado em pedaços</li><li>1 colher de chá de sementes de linhaça moída</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Verta o kefir natural fresco diretamente para uma taça funda de pequeno-almoço.</li><li><b>Adicionar:</b> Distribua os cubos de figo fresco e polvilhe uniformemente com as sementes de linhaça.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_PANQUECA_ALFARROBA_CALDA_FRAMBOESA + "', '<h3>Ingredientes:</h3><ul><li>1 ovo inteiro e 2 colheres de farinha de aveia</li><li>1 colher de sopa de alfarroba em pó</li><li>3 colheres de framboesas esmagadas</li></ul><h3>Preparação:</h3><ol><li><b>Cozzer:</b> Bata o ovo com a aveia e a alfarroba. Cozinhe a panqueca numa frigideira antiaderente quente.</li><li><b>Calda:</b> Cubra a panqueca pronta com o puré puro de framboesas frescas esmagadas com um garfo.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_GALETTE_INTEGRAL_UVAS_ASSADAS + "', '<h3>Ingredientes:</h3><ul><li>1 mini disco de massa integral pronta</li><li>1/2 chávena de uvas doces sem grainha</li></ul><h3>Preparação:</h3><ol><li><b>Rechear:</b> Coloque as uvas cortadas ao meio no centro da massa e dobre as abas laterais para dentro.</li><li><b>Assar:</b> Leve ao forno num tabuleiro até dourar a massa integral e as uvas ficarem bem macias.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_TORRADA_PATE_COGUMELOS_ALHO + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão saloio ou rústico</li><li>3 cogumelos brancos picados finamente</li><li>1 dente de alho pequeno e um fio de azeite</li></ul><h3>Preparação:</h3><ol><li><b>Paté:</b> Salteie os cogumelos com o alho picado em azeite e triture tudo até formar uma pasta fina.</li><li><b>Servir:</b> Torre a fatia de pão saloio e espalhe este paté caseiro aromático por cima enquanto quente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_SMOOTHIE_BOWL_ABOBORA_AVEIA_CHIA + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de puré de abóbora cozida</li><li>2 colheres de aveia e 1 colher de chia</li><li>1/2 chávena de bebida vegetal suave</li></ul><h3>Preparação:</h3><ol><li><b>Bater:</b> Triture o puré de abóbora, a aveia, a chia e a bebida vegetal no liquidificador até engrossar.</li><li><b>Empratar:</b> Verta o preparado espesso para uma taça funda e consuma fresco com a ajuda de uma colher.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_PAPA_TRIGO_SARRACENO_CHOCOLATE + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de sopa de flocos de trigo sarraceno</li><li>1 chávena de leite vegetal à escolha</li><li>1 quadrado pequeno de chocolate negro</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Coza os flocos de trigo sarraceno no leite vegetal mexendo sempre até criar consistência.</li><li><b>Derreter:</b> Adicione o quadrado de chocolate negro no fim e mexa até que este se dissolva na papa quente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_TORRADA_REQUEIJAO_VEG_DOCE_MACA + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão rústico torrado</li><li>2 colheres de sopa de requeijão vegetal</li><li>1 colher de chá de doce de maçã caseiro</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Cubra a superfície da fatia de pão rústico torrado com uma boa camada de requeijão vegetal.</li><li><b>Finalizar:</b> Adicione o doce de maçã por cima espalhando delicadamente para criar um contraste delicioso.</li></ol>');");

        // ==========================================
// ALMOÇOS - SETEMBRO (TODOS OS 30 DIAS)
// ==========================================

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_ARROZ_FORNO_COGUMELOS_CASTANHAS + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de arroz carolino</li><li>150 g de cogumelos variados frescos</li><li>100 g de castanhas cozidas picadas</li></ul><h3>Preparação:</h3><ol><li><b>Refogar:</b> Salteie os cogumelos e as castanhas num fundo de azeite e alho até dourarem.</li><li><b>Cozer e Assar:</b> Junte o arroz, adicione água a ferver e leve ao forno num tabuleiro até secar e ficar tostado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_ESTUFADO_GRAO_ABOBORA_MENINA + "', '<h3>Ingredientes:</h3><ul><li>2 chávenas de grão-de-bico cozido</li><li>200 g de abóbora-menina em cubos</li><li>1/2 cebola e polpa de tomate</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Faça um refogado leve com cebola e polpa de tomate num fio de azeite.</li><li><b>Estufar:</b> Adicione os cubos de abóbora e o grão, tape o tacho e deixe cozinhar em lume brando até a abóbora amaciar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_FEIJOADA_TRANSMONTANA_VEGETARIANA + "', '<h3>Ingredientes:</h3><ul><li>2 chávenas de feijão vermelho cozido</li><li>1 cenoura, 1/4 de couve lombarda</li><li>Chouriço vegetariano em rodelas</li></ul><h3>Preparação:</h3><ol><li><b>Legumes:</b> Coza a cenoura às rodelas e a couve cortada em pedaços num caldo aromático de ervas.</li><li><b>Apurar:</b> Junte o feijão vermelho e o chouriço vegetariano, deixando apurar até o molho ficar bem rico e espesso.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_RISOTO_ABOBORA_ASSADA_SALVIA + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de arroz arbóreo</li><li>150 g de abóbora assada em puré</li><li>Folhas de sálvia fresca e caldo vegetal</li></ul><h3>Preparação:</h3><ol><li><b>Arroz:</b> Aloure o arroz e vá vertendo o caldo vegetal a ferver aos poucos, mexendo sempre.</li><li><b>Envolver:</b> A meio do processo, incorpore o puré de abóbora assada e termine com as folhas de sálvia.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_MASSA_INTEGRAL_COGUMELOS_PORTOBELLO + "', '<h3>Ingredientes:</h3><ul><li>150 g de massa integral à escolha</li><li>2 cogumelos Portobello grandes fatiados</li><li>Alho, azeite e salsa picada</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Coza a massa integral em água a ferver com sal até ficar com a textura al dente.</li><li><b>Cogumelos:</b> Salteie os Portobello fatiados em azeite e alho, envolvendo a massa escorrida no final com salsa.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_EMPADAO_LENTILHAS_PURE_BATATA_DOCE + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de lentilhas castanhas cozidas</li><li>2 batatas-doces médias cozidas</li><li>Cebola, alho e bebida vegetal</li></ul><h3>Preparação:</h3><ol><li><b>Recheio:</b> Faça um estufado seco de lentilhas com cebola, alho e os temperos que mais gostar.</li><li><b>Montar:</b> Esmague as batatas-doces com um pouco de bebida vegetal, cubra as lentilhas num pirex e leve a dourar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_CARIL_GRAO_BICO_BATATA_DOCE + "', '<h3>Ingredientes:</h3><ul><li>2 chávenas de grão-de-bico cozido</li><li>1 batata-doce média em cubos</li><li>1 colher de caril e leite de coco</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Coza os cubos de batata-doce no leite de coco diluído em água com a colher de caril.</li><li><b>Apurar:</b> Incorpore o grão-de-bico cozido quando a batata estiver macia e deixe o molho reduzir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_SALADA_QUENTE_TRIGO_SARRACENO_COGUMELO + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de trigo sarraceno cozido</li><li>100 g de cogumelos frescos salteados</li><li>Folhas de espinafres e passas</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Envolva o trigo sarraceno ainda quente com os cogumelos salteados e as passas de uva.</li><li><b>Murchar:</b> Junte os espinafres frescos, misturando delicadamente para que murchem apenas com o calor residual.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_LASANHA_ESPINAFRE_RICOTA_CAJU + "', '<h3>Ingredientes:</h3><ul><li>Placas de lasanha, 200 g de espinafres</li><li>1 chávena de creme de ricota de caju</li><li>Molho de tomate caseiro</li></ul><h3>Preparação:</h3><ol><li><b>Camadas:</b> Alterne num pirex o molho de tomate, as placas de massa, os espinafres e a ricota de caju.</li><li><b>Assar:</b> Termine com uma camada de creme de caju e leve ao forno até a massa estar totalmente cozida.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_HAMBURGUER_LENTILHAS_ARROZ_ESCAROLA + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de lentilhas e arroz misturados</li><li>1/2 chávena de escarola picada finamente</li><li>Farinha de aveia para dar ponto</li></ul><h3>Preparação:</h3><ol><li><b>Moldar:</b> Esmague as lentilhas com o arroz, envolva a escarola e adicione aveia até conseguir moldar os hambúrgueres.</li><li><b>Grelhar:</b> Cozinhe os hambúrgueres numa frigideira antiaderente levemente untada até dourarem de ambos os lados.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_COUSCOUS_MARROQUINO_LEGUMES_RAIZ + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de couscous, 1 cenoura</li><li>1 nabo pequeno, 100 g de abóbora</li><li>Especiarias marroquinas a gosto</li></ul><h3>Preparação:</h3><ol><li><b>Legumes:</b> Corte os legumes de raiz em cubos e coza-os lentamente com as especiarias aromáticas.</li><li><b>Hidratar:</b> Verta o caldo quente sobre o couscous seco, tape por cinco minutos e solte com um garfo antes de juntar os legumes.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_TOFU_ESTUFADO_MOLHO_VINHO_TINTO + "', '<h3>Ingredientes:</h3><ul><li>200 g de tofu firme em cubos</li><li>1/2 chávena de vinho tinto de boa qualidade</li><li>Cebolinhas, cenoura e louro</li></ul><h3>Preparação:</h3><ol><li><b>Selar:</b> Doure os cubos de tofu numa panela com azeite. Adicione as cebolinhas, a cenoura e o louro.</li><li><b>Estufar:</b> Regue com o vinho tinto, tape a panela e deixe estufar em lume brando até o molho reduzir e encorpar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_CANELONES_RECHEADOS_LENTILHAS_TOMATE + "', '<h3>Ingredientes:</h3><ul><li>Tubos de canelones, 1 chávena de lentilhas</li><li>Molho de tomate e manjericão fresco</li><li>Cebola picada para o refogado</li></ul><h3>Preparação:</h3><ol><li><b>Recheio:</b> Cozinhe as lentilhas num refogado rico de tomate e use a mistura para rechear os tubos de canelones.</li><li><b>Forno:</b> Disponha os canelones num tabuleiro, cubra com o restante molho de tomate e leve a assar bem tapado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_ALMONDEGAS_FEIJAO_PRETO_ESPAGUETE + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de feijão preto cozido e esmagado</li><li>150 g de esparguete, molho de tomate</li><li>Pão ralado ou farinha de linhaça</li></ul><h3>Preparação:</h3><ol><li><b>Almôndegas:</b> Molde bolas com o feijão preto e o pão ralado. Grelhe ou asse as almôndegas até ficarem firmes.</li><li><b>Prato:</b> Coza o esparguete al dente e sirva coberto com as almôndegas e uma dose generosa de molho de tomate.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_STIR_FRY_TEMPEH_BROCOLOS_SESAMO + "', '<h3>Ingredientes:</h3><ul><li>150 g de tempeh em cubos pequenos</li><li>1 chávena de flores de brócolos frescos</li><li>Molho de soja, alho e sementes de sésamo</li></ul><h3>Preparação:</h3><ol><li><b>Wok:</b> Salteie o tempeh e os brócolos numa frigideira alta com alho e um fio de óleo de sésamo.</li><li><b>Finalizar:</b> Adicione o molho de soja na parte final do cozinhado e polvilhe com sementes de sésamo tostadas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_QUICHE_COGUMELOS_ALHO_FRANCES + "', '<h3>Ingredientes:</h3><ul><li>1 base de massa quebrada vegana</li><li>100 g de cogumelos, 1/2 alho-francês</li><li>200 ml de natas de soja ou aveia</li></ul><h3>Preparação:</h3><ol><li><b>Recheio:</b> Salteie os cogumelos fatiados com o alho-francês em rodelas até perderem toda a água.</li><li><b>Assar:</b> Envolva os legumes nas natas de soja, verta sobre a massa quebrada e leve ao forno até dourar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_BURRITO_BOWL_QUINOA_FEIJAO_PRETO + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de quinoa cozida simples</li><li>1/2 chávena de feijão preto cozido</li><li>Milho, tomate em cubos e coentros</li></ul><h3>Preparação:</h3><ol><li><b>Montagem:</b> Coloque a quinoa cozida na base de uma taça larga e funda de servir.</li><li><b>Guarnição:</b> Disponha o feijão, o milho e o tomate em secções separadas, finalizando com coentros frescos picados.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_GNOCCHI_ABOBORA_CREME_NOZ + "', '<h3>Ingredientes:</h3><ul><li>200 g de gnocchi de abóbora prontos</li><li>1/2 chávena de miolo de noz picado</li><li>100 ml de creme culinário vegetal</li></ul><h3>Preparação:</h3><ol><li><b>Creme:</b> Aqueça o creme vegetal com as nozes picadas numa frigideira até libertar aroma.</li><li><b>Gnocchi:</b> Coza os gnocchi em água a ferver, escorra assim que flutuarem e envolva de imediato no creme de noz.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_XAREM_ALGARVIO_BROCOLOS_TOFU + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de farinha de milho fina</li><li>100 g de tofu fumado em cubos</li><li>1/2 chávena de brócolos cozidos bem picados</li></ul><h3>Preparação:</h3><ol><li><b>Xarém:</b> Cozinhe a farinha de milho em água ou caldo vegetal mexendo sempre até obter uma papa espessa.</li><li><b>Acompanhar:</b> Envolva os brócolos picados na papa e sirva com o tofu fumado salteado por cima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_SALADA_QUENTE_GRAO_BETERRABA_ASSADA + "', '<h3>Ingredientes:</h3><ul><li>1 chávena e meia de grão-de-bico cozido</li><li>1 beterraba média assada em cubos</li><li>Rúcula selvagem e vinagre balsâmico</li></ul><h3>Preparação:</h3><ol><li><b>Aquecer:</b> Aqueça o grão-de-bico com um fio de azeite numa frigideira juntamente com a beterraba assada.</li><li><b>Salada:</b> Retire do lume, envolva as folhas de rúcula frescas e tempere com um fio de vinagre balsâmico.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_PAELLA_OUTONO_COGUMELOS_ALCACHOFRA + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de arroz bomba ou vaporizado</li><li>100 g de cogumelos, 3 corações de alcachofra</li><li>Açafrão e caldo de legumes</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Doure os cogumelos e as alcachofras na paelheira com azeite, alho e açafrão em pó.</li><li><b>Cozedura:</b> Junte o arroz, adicione o caldo de legumes quente e cozinhe sem mexer até o líquido evaporar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_SEITAN_ASSADO_FORNO_BATATINHAS + "', '<h3>Ingredientes:</h3><ul><li>200 g de seitan caseiro fatiado</li><li>6 batatas pequenas para assar</li><li>Alho, louro, pimentão doce e vinho branco</li></ul><h3>Preparação:</h3><ol><li><b>Marinar:</b> Tempere o seitan e as batatas com alho esmagado, louro, pimentão doce e vinho branco.</li><li><b>Assar:</b> Disponha tudo num tabuleiro de barro e leve ao forno até as batatas ficarem macias e douradas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_FAVAL_A_PORTUGUESA_VEGANO + "', '<h3>Ingredientes:</h3><ul><li>2 chávenas de favas tenras descascadas</li><li>Chouriço e morcela vegetarianos</li><li>Coentros frescos e um dente de alho</li></ul><h3>Preparação:</h3><ol><li><b>Estufar:</b> Cozinhe as favas em lume brando com alho, coentros e um pouco de água até estarem macias.</li><li><b>Envolver:</b> Adicione os enchidos vegetarianos fatiados e deixe apurar tapado para libertar os aromas tradicionais.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_WRAP_QUENTE_GRAO_ESPINAFRE_TAHINI + "', '<h3>Ingredientes:</h3><ul><li>1 tortilha grande de trigo ou integral</li><li>1/2 chávena de grão salteado, espinafres</li><li>1 colher de sopa de molho tahini</li></ul><h3>Preparação:</h3><ol><li><b>Recheio:</b> Coloque o grão quente e os espinafres levemente murchos no centro da tortilha.</li><li><b>Fechar:</b> Regue com o molho tahini espesso, dobre o wrap bem apertado e passe na frigideira para dourar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_TACOS_COGUMELOS_SHIITAKE_CEBOLA + "', '<h3>Ingredientes:</h3><ul><li>3 tortilhas de milho pequenas para tacos</li><li>150 g de cogumelos Shiitake fatiados</li><li>1/2 cebola roxa cortada em meias-luas</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Cozinhe os Shiitake e a cebola roxa em lume forte com um fio de azeite até dourarem bem.</li><li><b>Montar:</b> Aqueça as tortilhas de milho numa chapa e recheie generosamente com a mistura de cogumelos quente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_RISOTO_COGUMELOS_PORCINI_TOMILHO + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de arroz arbóreo</li><li>20 g de cogumelos porcini secos</li><li>Tomilho fresco e caldo da hidratação</li></ul><h3>Preparação:</h3><ol><li><b>Hidratar:</b> Coloque os porcini em água a ferver por vinte minutos. Use essa água quente como caldo.</li><li><b>Cozinhar:</b> Vá adicionando o caldo ao arroz aos poucos. No fim, junte os porcini e ramos de tomilho fresco.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_ESTUFADO_FEIJAO_BRANCO_COUVE_GALEGA + "', '<h3>Ingredientes:</h3><ul><li>2 chávenas de feijão branco cozido</li><li>1 chávena de couve galega cortada fina</li><li>Cebola, alho e cenoura em cubos</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Refogue a cebola, o alho e os cubos de cenoura até que fiquem bem macios.</li><li><b>Cozinhar:</b> Adicione o feijão branco com o seu caldo e a couve galega, deixando ferver até a couve cozer.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_MAC_AND_CHEESE_BATATA_DOCE_CAJU + "', '<h3>Ingredientes:</h3><ul><li>150 g de massa macarrão, 1 batata-doce</li><li>1/2 chávena de cajus demolhados</li><li>Levedura de cerveja para sabor a queijo</li></ul><h3>Preparação:</h3><ol><li><b>Molho:</b> Triture a batata-doce cozida com os cajus, a levedura de cerveja e água até obter um creme liso.</li><li><b>Misturar:</b> Coza a massa, escorra a água e envolva muito bem no creme de queijo vegetal quente antes de servir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_TORTILHA_FORNO_LEGUMES_OUTONO + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de cubos de abóbora e cenoura</li><li>3 ovos batidos frescos</li><li>Ervas aromáticas a gosto</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Envolva os cubos de legumes previamente cozidos ou assados nos ovos batidos temperados.</li><li><b>Forno:</b> Verta tudo numa forma antiaderente redonda e leve ao forno até a tortilha prender e dourar à superfície.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_SET_SALADA_WARM_LENTILHAS_BELUGA_PERA + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de lentilhas beluga cozidas</li><li>1/2 pera rocha firme fatiada</li><li>Folhas verdes mistas e nozes picadas</li></ul><h3>Preparação:</h3><ol><li><b>Grelhar:</b> Passe as fatias de pera numa frigideira antiaderente quente até dourarem de ambos os lados.</li><li><b>Empratar:</b> Junte as lentilhas beluga mornas com a pera grelhada, as folhas verdes e termine com as nozes.</li></ol>');");

