        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_RISOTO_CEVADA_COGUMELOS + "', '<h3>Ingredientes:</h3><ul><li>Cevada, cogumelos, caldo vegetal</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Prepare a cevada até ficar cremosa.</li><li><b>Finalizar:</b> Junte os cogumelos salteados.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_TOFU_LAGAREIRO_BATATA_MURRO + "', '<h3>Ingredientes:</h3><ul><li>Tofu, batatas pequenas, muito alho</li><li>Azeite</li></ul><h3>Preparação:</h3><ol><li><b>Assar:</b> Asse as batatas e o tofu com muito azeite e alho.</li><li><b>Servir:</b> Típico prato português.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_MASSA_FORNO_ABOBORA_SALVIA + "', '<h3>Ingredientes:</h3><ul><li>Massa, abóbora assada, sálvia</li></ul><h3>Preparação:</h3><ol><li><b>Envolver:</b> Misture a massa com a abóbora.</li><li><b>Assar:</b> Leve ao forno com sálvia fresca.</li></ol>');");

