        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_ALMONDEGAS_BOLOTA_MOLHO_TOMATE + "', '<h3>Ingredientes:</h3><ul><li>Farinha de bolota, tomate</li><li>Ervas aromáticas</li></ul><h3>Preparação:</h3><ol><li><b>Estufar:</b> Cozinhe as almôndegas no molho.</li><li><b>Servir:</b> Acompanhe com massa.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_QUICHE_SEM_MASSA_GRELOS_TOFU + "', '<h3>Ingredientes:</h3><ul><li>Grelos, tofu, base de ovo vegan</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Junte os ingredientes numa forma.</li><li><b>Assar:</b> Leve ao forno até firmar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_XAREM_ALGARVIO_AMEIJOA_VEG + "', '<h3>Ingredientes:</h3><ul><li>Farinha de milho, cogumelos</li><li>Coentros</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Prepare o xarém tradicional.</li><li><b>Finalizar:</b> Junte os cogumelos antes de servir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_GNOCCHI_CASTANHA_MANTEIGA_SALVIA + "', '<h3>Ingredientes:</h3><ul><li>Gnocchi, castanhas, manteiga vegan</li><li>Sálvia</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Frite na frigideira.</li><li><b>Servir:</b> Prato festivo.</li></ol>');");

