        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_CANELONES_RECHEADOS_ESPINAFRE_RICOTA + "', '<h3>Ingredientes:</h3><ul><li>Massa, espinafres, requeijão vegan</li></ul><h3>Preparação:</h3><ol><li><b>Rechear:</b> Encha os canelones.</li><li><b>Assar:</b> Leve ao forno com tomate.</li></ol>');");

